    22→void UWjWorldBrickMovement::Initialize(UWjWorldBrickComponent* InBrickComponent, UWjWorldGameRuleApproachingWall* InGameRule)
    23→{
    24→	BrickComponent = InBrickComponent;
    25→	GameRule = InGameRule;
    26→	WallManger = InGameRule ? InGameRule->GetWallManager() : nullptr;
    27→
    28→	if(BrickComponent.IsValid())
    29→	{
    30→		CurrentGridPosition = BrickComponent->GetBrickProperties().SpawnedGridPosition;
    31→		TargetActor = BrickComponent->GetOwner();
    32→	}
    33→}
    34→
    35→void UWjWorldBrickMovement::Tick(float DeltaTime)
    36→{
    37→	if (bIsMoving == false) return;
    38→
    39→	MoveElapsedTime += DeltaTime;
    40→
    41→	FVector NewLocation = FVector::ZeroVector;
    42→	FVector BoxExtent = BrickComponent.IsValid() ? BrickComponent->GetBrickProperties().Size : FVector::ZeroVector;
    43→
    44→	bool bWallManagerMoving = WallManger.IsValid() ? WallManger->IsWallMoving() : false;
    45→
    46→	// 이동 중인 벽돌에 Z 오프셋 적용 (Z-Fight 방지)
    47→	constexpr float MovingZOffset = 5.0f;
    48→
    49→	if (MoveElapsedTime >= MoveAllowTime
    50→		|| bWallManagerMoving == false)
    51→	{
    52→		NewLocation = EndLocation; // 이동 완료 시 원래 Z 위치로 복귀
    53→		bIsMoving = false;
    54→		MoveElapsedTime = 0.0f;
    55→		if (TargetActor.IsValid())
    56→		{
    57→			TargetActor->SetActorLocation(NewLocation);
    58→		}
    59→	}
    60→	else
    61→	{
    62→		float Alpha = MoveElapsedTime / MoveAllowTime;
    63→		NewLocation = FMath::Lerp(StartLocation, EndLocation, Alpha);
    64→		NewLocation.Z += MovingZOffset; // 이동 중에는 약간 위로 띄움
    65→		if (TargetActor.IsValid())
    66→		{
    67→			TargetActor->SetActorLocation(NewLocation);
    68→		}
    69→	}
    70→
    71→	// Standard 타입 벽돌만 다른 벽돌과의 충돌 체크
    72→	if (BrickComponent.IsValid() && BrickComponent->GetBrickProperties().BrickType == EWjWorldBrickType::Standard)
    73→	{
    74→		CheckCollisionWithOtherBricks();
    75→	}
    76→
    77→	// 이동 중인 벽돌이 Pawn과 겹치면 이동 방향으로 밀어냄
    78→	if (BrickComponent.IsValid() && bIsMoving)
    79→	{
    80→		FVector BrickHalfSize = BoxExtent * 0.5f;
    81→
    82→		TArray<FOverlapResult> PawnOverlaps;
    83→		FCollisionShape PawnCheckShape = FCollisionShape::MakeBox(BrickHalfSize);
    84→
    85→		if (GetWorld()->OverlapMultiByChannel(
    86→			PawnOverlaps,
    87→			NewLocation,
    88→			FQuat::Identity,
    89→			ECC_Pawn,
    90→			PawnCheckShape))
    91→		{
    92→			for (const FOverlapResult& Overlap : PawnOverlaps)
    93→			{
    94→				AWjWorldCharacterPlay* CharacterPlay = Cast<AWjWorldCharacterPlay>(Overlap.GetActor());
    95→				if (!CharacterPlay) continue;
    96→				if (CharacterPlay->IsEliminated()) continue;
    97→
    98→				float CapsuleRadius = CharacterPlay->GetCapsuleComponent()->GetScaledCapsuleRadius();
    99→
   100→				FVector MoveDir = MovementVector.GetSafeNormal();
   101→				if (MoveDir.IsNearlyZero()) continue;
   102→
   103→				// 벽돌 반 크기 + 캡슐 반지름 + 여유값
   104→				float PushDistance = 0.0f;
   105→				if (FMath::Abs(MoveDir.X) > FMath::Abs(MoveDir.Y))
   106→				{
   107→					PushDistance = BrickHalfSize.X + CapsuleRadius + 5.0f;
   108→				}
   109→				else
   110→				{
   111→					PushDistance = BrickHalfSize.Y + CapsuleRadius + 5.0f;
   112→				}
   113→
   114→				FVector PushTarget = NewLocation + MoveDir * PushDistance;
   115→				PushTarget.Z = CharacterPlay->GetActorLocation().Z; // Z축 유지
   116→
   117→				// 끼임 체크: 밀려날 위치에 벽돌이 있는지 확인
   118→				bool bIsTrapped = false;
   119→				UWjWorldBrickComponent* BlockingBrick = FindBrickAtLocation(PushTarget);
   120→				if (BlockingBrick)
   121→				{
   122→					bIsTrapped = true;
   123→				}
   124→				else
   125→				{
   126→					// 맵 경계 체크
   127→					const FWjWorldBrickProperties& BrickProperties = BrickComponent->GetBrickProperties();
   128→					FIntPoint GridIndex = UWjWorldBrickSpawner::CalculateBrickGridIndex(
   129→						PushTarget,
   130→						BrickProperties.ColumnNum,
   131→						BrickProperties.RowNum,
   132→						BrickProperties.CenterOffset,
   133→						BrickProperties.Size
   134→					);
   135→
   136→					if (GridIndex.X < 0 || GridIndex.X >= BrickProperties.ColumnNum ||
   137→						GridIndex.Y < 0 || GridIndex.Y >= BrickProperties.RowNum)
   138→					{
   139→						bIsTrapped = true;
   140→					}
   141→				}
   142→
   143→				if (bIsTrapped)
   144→				{
   145→					// 끼임 발생 → 플레이어 제거
   146→					UE_LOG(LogWjWorld, Warning, TEXT("Player trapped between bricks - eliminating"));
   147→					if (GameRule.IsValid())
   148→					{
   149→						GameRule->OnPlayerEliminated(CharacterPlay);
   150→					}
   151→				}
   152→				else
   153→				{
   154→					// 정상적으로 밀어냄
   155→					CharacterPlay->SetActorLocation(PushTarget);
   156→				}
   157→			}
   158→		}
   159→	}
   160→}
   161→
   162→void UWjWorldBrickMovement::MoveBrick(float InMoveAllowTime)
   163→{
   164→	if (!BrickComponent.IsValid()) return;
   165→
   166→	bIsMoving = true;
   167→
   168→	TargetActor = BrickComponent->GetOwner();
   169→	StartLocation = BrickComponent->GetComponentLocation();
   170→	EndLocation = StartLocation + GetMovementVector(true);
   171→	MoveAllowTime = InMoveAllowTime;
   172→	MoveElapsedTime = 0.0f;
   173→
   174→	if(StartLocation.Equals(EndLocation))
   175→	{
   176→		bIsMoving = false;
   177→		BrickComponent->ReserveDestroyBrick(InMoveAllowTime);
   178→	}
   179→}
   180→
   181→FVector UWjWorldBrickMovement::GetMovementVector(bool bIsNew)
   182→{
   183→	if (!BrickComponent.IsValid()) return FVector();
   184→	
   185→	if (bIsNew)
   186→	{
   187→		LastMovementVector = MovementVector;
   188→	}
   189→
   190→	TArray<EWjWorldBrickMovementDirection> MovementDirs = GetNextDirections();
   191→	const FWjWorldBrickProperties& BrickProperties = BrickComponent->GetBrickProperties();
   192→
   193→	for(EWjWorldBrickMovementDirection Direction : MovementDirs)
   194→	{
   195→		switch (Direction)
   196→		{
   197→		case EWjWorldBrickMovementDirection::Up:
   198→			++CurrentGridPosition.Y;
   199→			break;
   200→		case EWjWorldBrickMovementDirection::Right:
   201→			++CurrentGridPosition.X;
   202→			break;
   203→		case EWjWorldBrickMovementDirection::Down:
   204→			--CurrentGridPosition.Y;
   205→			break;
   206→		case EWjWorldBrickMovementDirection::Left:
   207→			--CurrentGridPosition.X;
   208→			break;
   209→		}
   210→	}
   211→
   212→	EndLocation = UWjWorldBrickSpawner::CalculateBrickPosition
   213→	(
   214→		CurrentGridPosition.X,
   215→		CurrentGridPosition.Y,
   216→		BrickProperties.ColumnNum,
   217→		BrickProperties.RowNum,
   218→		BrickProperties.CenterOffset,
   219→		BrickProperties.Size
   220→	);
   221→
   222→	MovementVector = EndLocation - StartLocation;
   223→
   224→	return MovementVector;
   225→}
   226→
   227→TArray<EWjWorldBrickMovementDirection> UWjWorldBrickMovement::GetNextDirections()
   228→{
   229→	if (!BrickComponent.IsValid()) return TArray<EWjWorldBrickMovementDirection>();
   230→	if (!GameRule.IsValid()) return TArray<EWjWorldBrickMovementDirection>();
   231→
   232→	TArray<EWjWorldBrickMovementDirection> Result;
   233→	const TSet<FIntPoint>& FloodFillPoints = GameRule->GetFloodFillPoints();
   234→
   235→	struct FPointWithDirection
   236→	{
   237→		FIntPoint Point;
   238→		EWjWorldBrickMovementDirection Direction;
   239→	};
   240→
   241→	TArray<FPointWithDirection> CheckPoints = {
   242→		{ FIntPoint(CurrentGridPosition.X + 1, CurrentGridPosition.Y), EWjWorldBrickMovementDirection::Right },
   243→		{ FIntPoint(CurrentGridPosition.X - 1, CurrentGridPosition.Y), EWjWorldBrickMovementDirection::Left },
   244→		{ FIntPoint(CurrentGridPosition.X, CurrentGridPosition.Y + 1), EWjWorldBrickMovementDirection::Up },
   245→		{ FIntPoint(CurrentGridPosition.X, CurrentGridPosition.Y - 1), EWjWorldBrickMovementDirection::Down }
   246→	};
   247→
   248→	for (const auto& CheckPoint : CheckPoints)
   249→	{
   250→		if (FloodFillPoints.Contains(CheckPoint.Point))
   251→		{
   252→			Result.Add(CheckPoint.Direction);
   253→		}
   254→	}
   255→
   256→	return Result;
   257→}
   258→
   259→void UWjWorldBrickMovement::PushBrick(const FVector& Direction, float InMoveAllowTime)
   260→{
   261→	if (!BrickComponent.IsValid()) return;
   262→	if (bIsMoving) return; // 이미 이동 중이면 무시
   263→
   264→	// 연쇄 밀림 체크: 밀릴 수 있는지, 밀어야 할 벽돌 목록 수집
   265→	TArray<UWjWorldBrickComponent*> BricksToMove;
   266→	bool bCanPush = CanPushInDirection(Direction, BricksToMove);
   267→
   268→	if (!bCanPush)
   269→	{
   270→		// 막혀서 밀 수 없음 -> 파괴
   271→		UE_LOG(LogWjWorld, Log, TEXT("PushBrick blocked, destroying brick at %s"), *BrickComponent->GetComponentLocation().ToString());
   272→		BrickComponent->ReserveDestroyBrick(0.0f);
   273→		return;
   274→	}
   275→
   276→	// 연쇄 밀림: 뒤에서부터 밀어야 충돌 안 함
   277→	for (int32 i = BricksToMove.Num() - 1; i >= 0; --i)
   278→	{
   279→		UWjWorldBrickComponent* BrickToMove = BricksToMove[i];
   280→		if (BrickToMove && BrickToMove != BrickComponent.Get())
   281→		{
   282→			if (UWjWorldBrickMovement* OtherMovement = BrickToMove->GetBrickMovement())
   283→			{
   284→				OtherMovement->ExecutePush(Direction, InMoveAllowTime);
   285→			}
   286→		}
   287→	}
   288→
   289→	// 자신도 밀림
   290→	ExecutePush(Direction, InMoveAllowTime);
   291→}
   292→
   293→void UWjWorldBrickMovement::ExecutePush(const FVector& Direction, float InMoveAllowTime)
   294→{
   295→	if (!BrickComponent.IsValid()) return;
   296→	if (bIsMoving) return;
   297→
   298→	bIsMoving = true;
   299→
   300→	TargetActor = BrickComponent->GetOwner();
   301→	StartLocation = BrickComponent->GetComponentLocation();
   302→
   303→	// Direction을 정규화하고 벽돌 크기만큼 이동
   304→	FVector NormalizedDir = Direction.GetSafeNormal();
   305→	const FWjWorldBrickProperties& BrickProperties = BrickComponent->GetBrickProperties();
   306→
   307→	// 이동 방향에 따라 적절한 거리 계산
   308→	FVector MoveDistance = FVector::ZeroVector;
   309→	if (FMath::Abs(NormalizedDir.X) > FMath::Abs(NormalizedDir.Y))
   310→	{
   311→		MoveDistance.X = FMath::Sign(NormalizedDir.X) * BrickProperties.Size.X;
   312→	}
   313→	else
   314→	{
   315→		MoveDistance.Y = FMath::Sign(NormalizedDir.Y) * BrickProperties.Size.Y;
   316→	}
   317→
   318→	EndLocation = StartLocation + MoveDistance;
   319→	MoveAllowTime = InMoveAllowTime;
   320→	MoveElapsedTime = 0.0f;
   321→	MovementVector = MoveDistance;
   322→
   323→	UE_LOG(LogWjWorld, Log, TEXT("ExecutePush: %s -> %s"), *StartLocation.ToString(), *EndLocation.ToString());
   324→}
   325→
   326→bool UWjWorldBrickMovement::CanPushInDirection(const FVector& Direction, TArray<UWjWorldBrickComponent*>& OutBricksToMove)
   327→{
   328→	if (!BrickComponent.IsValid()) return false;
   329→
   330→	const FWjWorldBrickProperties& BrickProperties = BrickComponent->GetBrickProperties();
   331→	FVector CurrentCheckLocation = BrickComponent->GetComponentLocation();
   332→
   333→	// Direction을 정규화하고 벽돌 크기만큼 이동 거리 계산
   334→	FVector NormalizedDir = Direction.GetSafeNormal();
   335→	FVector MoveDistance = FVector::ZeroVector;
   336→	if (FMath::Abs(NormalizedDir.X) > FMath::Abs(NormalizedDir.Y))
   337→	{
   338→		MoveDistance.X = FMath::Sign(NormalizedDir.X) * BrickProperties.Size.X;
   339→	}
   340→	else
   341→	{
   342→		MoveDistance.Y = FMath::Sign(NormalizedDir.Y) * BrickProperties.Size.Y;
   343→	}
   344→
   345→	// 자신을 목록에 추가
   346→	OutBricksToMove.Add(BrickComponent.Get());
   347→
   348→	// 다음 위치 체크
   349→	FVector NextLocation = CurrentCheckLocation + MoveDistance;
   350→
   351→	// 최대 체크 횟수 (무한 루프 방지)
   352→	const int32 MaxChainLength = 20;
   353→	int32 ChainCount = 0;
   354→
   355→	while (ChainCount < MaxChainLength)
   356→	{
   357→		++ChainCount;
   358→
   359→		// 다음 위치가 막혀있는지 체크 (Standard 벽돌, 맵 경계 등)
   360→		if (IsLocationBlocked(NextLocation))
   361→		{
   362→			return false; // 막혀있으면 밀 수 없음
   363→		}
   364→
   365→		// 다음 위치에 Moving 타입 벽돌이 있는지 체크
   366→		UWjWorldBrickComponent* BrickAtNext = FindBrickAtLocation(NextLocation);
   367→		if (BrickAtNext)
   368→		{
   369→			if (BrickAtNext->GetBrickProperties().BrickType == EWjWorldBrickType::Moving)
   370→			{
   371→				// Moving 벽돌 발견 -> 연쇄 밀림 대상에 추가
   372→				OutBricksToMove.Add(BrickAtNext);
   373→				NextLocation = NextLocation + MoveDistance;
   374→				continue;
   375→			}
   376→			else if (BrickAtNext->GetBrickProperties().BrickType == EWjWorldBrickType::Standard)
   377→			{
   378→				// Standard 벽돌에 막힘
   379→				return false;
   380→			}
   381→			else
   382→			{
   383→				// Destructible, Explosive 등은 밀 수 있음 (해당 벽돌은 파괴됨)
   384→				break;
   385→			}
   386→		}
   387→		else
   388→		{
   389→			// 빈 공간 -> 밀 수 있음
   390→			break;
   391→		}
   392→	}
   393→
   394→	return true;
   395→}
