   397→void UWjWorldBrickMovement::CheckCollisionWithOtherBricks()
   398→{
   399→	if (!BrickComponent.IsValid()) return;
   400→	if (!TargetActor.IsValid()) return;
   401→
   402→	const FWjWorldBrickProperties& BrickProperties = BrickComponent->GetBrickProperties();
   403→	const FVector CurrentLocation = TargetActor->GetActorLocation();
   404→	const FVector HalfSize = BrickProperties.Size * 0.4f; // 약간 작게 체크
   405→
   406→	TArray<FOverlapResult> Overlaps;
   407→	FCollisionShape CollisionShape = FCollisionShape::MakeBox(HalfSize);
   408→
   409→	if (GetWorld()->OverlapMultiByObjectType(
   410→		Overlaps,
   411→		CurrentLocation,
   412→		FQuat::Identity,
   413→		FCollisionObjectQueryParams::AllObjects,
   414→		CollisionShape))
   415→	{
   416→		for (const FOverlapResult& Overlap : Overlaps)
   417→		{
   418→			AWjWorldBrickActor* OtherBrickActor = Cast<AWjWorldBrickActor>(Overlap.GetActor());
   419→			if (!OtherBrickActor) continue;
   420→			if (OtherBrickActor == TargetActor.Get()) continue; // 자기 자신 제외
   421→
   422→			UWjWorldBrickComponent* OtherBrickComponent = OtherBrickActor->GetBrickComponent();
   423→			if (!OtherBrickComponent) continue;
   424→
   425→			// Standard 타입이 아닌 벽돌만 충돌 처리
   426→			if (OtherBrickComponent->GetBrickProperties().BrickType != EWjWorldBrickType::Standard)
   427→			{
   428→				NotifyCollisionToBrick(OtherBrickComponent, MovementVector);
   429→			}
   430→		}
   431→	}
   432→}
   433→
   434→void UWjWorldBrickMovement::NotifyCollisionToBrick(UWjWorldBrickComponent* OtherBrick, const FVector& Direction)
   435→{
   436→	if (!OtherBrick) return;
   437→
   438→	OtherBrick->HandleWallCollision(Direction);
   439→}
   440→
   441→UWjWorldBrickComponent* UWjWorldBrickMovement::FindBrickAtLocation(const FVector& Location)
   442→{
   443→	if (!BrickComponent.IsValid()) return nullptr;
   444→
   445→	const FWjWorldBrickProperties& BrickProperties = BrickComponent->GetBrickProperties();
   446→	const FVector HalfSize = BrickProperties.Size * 0.3f; // 약간 작게 체크
   447→
   448→	TArray<FOverlapResult> Overlaps;
   449→	FCollisionShape CollisionShape = FCollisionShape::MakeBox(HalfSize);
   450→
   451→	if (GetWorld()->OverlapMultiByObjectType(
   452→		Overlaps,
   453→		Location,
   454→		FQuat::Identity,
   455→		FCollisionObjectQueryParams::AllObjects,
   456→		CollisionShape))
   457→	{
   458→		for (const FOverlapResult& Overlap : Overlaps)
   459→		{
   460→			AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(Overlap.GetActor());
   461→			if (!BrickActor) continue;
   462→			if (BrickActor == BrickComponent->GetOwner()) continue; // 자기 자신 제외
   463→
   464→			UWjWorldBrickComponent* FoundBrick = BrickActor->GetBrickComponent();
   465→			if (FoundBrick)
   466→			{
   467→				return FoundBrick;
   468→			}
   469→		}
   470→	}
   471→
   472→	return nullptr;
   473→}
   474→
   475→bool UWjWorldBrickMovement::IsLocationBlocked(const FVector& Location)
   476→{
   477→	if (!BrickComponent.IsValid()) return true;
   478→	if (!GameRule.IsValid()) return true;
   479→
   480→	const FWjWorldBrickProperties& BrickProperties = BrickComponent->GetBrickProperties();
   481→
   482→	// 그리드 인덱스로 변환하여 SafeZone 범위 체크
   483→	FIntPoint GridIndex = UWjWorldBrickSpawner::CalculateBrickGridIndex(
   484→		Location,
   485→		BrickProperties.ColumnNum,
   486→		BrickProperties.RowNum,
   487→		BrickProperties.CenterOffset,
   488→		BrickProperties.Size
   489→	);
   490→
   491→	// 맵 경계 체크
   492→	if (GridIndex.X < 0 || GridIndex.X >= BrickProperties.ColumnNum ||
   493→		GridIndex.Y < 0 || GridIndex.Y >= BrickProperties.RowNum)
   494→	{
   495→		return true; // 맵 밖으로 나가면 막힘
   496→	}
   497→
   498→	// 해당 위치에 Standard 벽돌이 있는지 체크
   499→	UWjWorldBrickComponent* BrickAtLocation = FindBrickAtLocation(Location);
   500→	if (BrickAtLocation && BrickAtLocation->GetBrickProperties().BrickType == EWjWorldBrickType::Standard)
   501→	{
   502→		return true; // Standard 벽돌에 막힘
   503→	}
   504→
   505→	return false;
   506→}
