    26→float UWjWorldWallManager::GetBrickMovementAllowedTime(int32 BrickMoveSignalCount)
    27→{
    28→	float DeltaTime = BrickMoveAllowedTimeMax;
    29→
    30→	float LevelRatio = FMath::Clamp(static_cast<float>(BrickMoveSignalCount) / static_cast<float>(MaxGameLevel), 0.0f, 1.0f);
    31→	float InverseRatio = 1.0f - LevelRatio;
    32→	DeltaTime = FMath::Lerp(BrickMoveAllowedTimeMin, BrickMoveAllowedTimeMax, InverseRatio);
    33→
    34→	return DeltaTime;
    35→}
