    69→void UWjWorldWallManager::PushCharactersInSafeZone()
    70→{
    71→	if (!GameRule.IsValid()) return;
    72→
    73→	UWorld* World = GetWorld();
    74→	if (!World) return;
    75→
    76→	const TSet<FIntPoint>& SafeZonePoints = GameRule->GetCurrentSafeZonePoints();
    77→	const FWjWorldWallDescription& WallDesc = GameRule->GetWallDesc();
    78→
    79→	if (SafeZonePoints.Num() == 0) return;
    80→
    81→	// 모든 플레이어 확인
    82→	for (auto Iter = World->GetPlayerControllerIterator(); Iter; ++Iter)
    83→	{
    84→		APlayerController* PC = Iter->Get();
    85→		if (!PC) continue;
    86→
    87→		ACharacter* Character = Cast<ACharacter>(PC->GetPawn());
    88→		if (!Character) continue;
    89→
    90→		FVector CharLocation = Character->GetActorLocation();
    91→
    92→		// 현재 위치의 그리드 인덱스 계산
    93→		FIntPoint CharGridIndex = UWjWorldBrickSpawner::CalculateBrickGridIndex(
    94→			CharLocation,
    95→			WallDesc.ColumnNum,
    96→			WallDesc.RowNum,
    97→			WallDesc.CenterOffset,
    98→			WallDesc.BrickSize
    99→		);
   100→
   101→		// 안전 구역 안에 있으면 스킵
   102→		if (SafeZonePoints.Contains(CharGridIndex))
   103→		{
   104→			continue;
   105→		}
   106→
   107→		// 안전 구역 밖에 있으면 가장 가까운 안전 구역으로 이동
   108→		float MinDistSq = MAX_FLT;
   109→		FIntPoint ClosestSafePoint = FIntPoint::ZeroValue;
   110→
   111→		for (const FIntPoint& SafePoint : SafeZonePoints)
   112→		{
   113→			FVector SafeWorldPos = UWjWorldBrickSpawner::CalculateBrickPosition(
   114→				SafePoint.X,
   115→				SafePoint.Y,
   116→				WallDesc.ColumnNum,
   117→				WallDesc.RowNum,
   118→				WallDesc.CenterOffset,
   119→				WallDesc.BrickSize
   120→			);
   121→
   122→			float DistSq = FVector::DistSquared(CharLocation, SafeWorldPos);
   123→			if (DistSq < MinDistSq)
   124→			{
   125→				MinDistSq = DistSq;
   126→				ClosestSafePoint = SafePoint;
   127→			}
   128→		}
   129→
   130→		FVector TargetLocation = UWjWorldBrickSpawner::CalculateBrickPosition(
   131→			ClosestSafePoint.X,
   132→			ClosestSafePoint.Y,
   133→			WallDesc.ColumnNum,
   134→			WallDesc.RowNum,
   135→			WallDesc.CenterOffset,
   136→			WallDesc.BrickSize
   137→		);
   138→
   139→		// Z축은 원래 캐릭터 위치 유지
   140→		TargetLocation.Z = CharLocation.Z;
   141→
   142→		Character->SetActorLocation(TargetLocation);
   143→
   144→		UE_LOG(LogWjWorld, Log, TEXT("PushCharactersInSafeZone: Pushed character from grid (%d,%d) to (%d,%d)"),
   145→			CharGridIndex.X, CharGridIndex.Y, ClosestSafePoint.X, ClosestSafePoint.Y);
   146→	}
   147→}
