   490→void UGA_SpawnBrick::CreateRefillEffect()
   491→{
   492→	if (RefillEffect)
   493→	{
   494→		return;
   495→	}
   496→
   497→	RefillEffect = NewObject<UGameplayEffect>(this, FName(TEXT("GE_SpawnBrickChargeRefill")));
   498→	RefillEffect->DurationPolicy = EGameplayEffectDurationType::Infinite;
   499→	RefillEffect->Period = FScalableFloat(ChargeRefillInterval);
   500→	RefillEffect->bExecutePeriodicEffectOnApplication = false;
   501→
   502→	FGameplayModifierInfo Modifier;
   503→	Modifier.Attribute = UWjWorldCharacterAttributeSet::GetSpawnBrickChargesAttribute();
   504→	Modifier.ModifierOp = EGameplayModOp::Additive;
   505→	Modifier.ModifierMagnitude = FGameplayEffectModifierMagnitude(FScalableFloat(1.f));
   506→	RefillEffect->Modifiers.Add(Modifier);
   507→}
