   509→void UGA_SpawnBrick::StartChargeRefill()
   510→{
   511→	UAbilitySystemComponent* ASC = GetAbilitySystemComponentFromActorInfo();
   512→	if (!ASC || !RefillEffect)
   513→	{
   514→		return;
   515→	}
   516→
   517→	// 이미 리필 중이면 무시
   518→	if (RefillEffectHandle.IsValid() && ASC->GetActiveGameplayEffect(RefillEffectHandle))
   519→	{
   520→		return;
   521→	}
   522→
   523→	FGameplayEffectContextHandle ContextHandle = ASC->MakeEffectContext();
   524→	FGameplayEffectSpec Spec(RefillEffect, ContextHandle, 1.f);
   525→	RefillEffectHandle = ASC->ApplyGameplayEffectSpecToSelf(Spec);
   526→
   527→	// 리필 시작 시각 기록
   528→	if (UWorld* World = GetWorld())
   529→	{
   530→		RefillStartWorldTime = World->GetTimeSeconds();
   531→	}
   532→
   533→	UE_LOG(LogWjWorldAbilities, Log, TEXT("UGA_SpawnBrick: 충전 리필 시작 (%.1f초 간격)"), ChargeRefillInterval);
   534→}
