   536→void UGA_SpawnBrick::StopChargeRefill()
   537→{
   538→	if (!RefillEffectHandle.IsValid())
   539→	{
   540→		return;
   541→	}
   542→
   543→	UAbilitySystemComponent* ASC = GetAbilitySystemComponentFromActorInfo();
   544→	if (ASC)
   545→	{
   546→		ASC->RemoveActiveGameplayEffect(RefillEffectHandle);
   547→	}
   548→
   549→	RefillEffectHandle.Invalidate();
   550→	RefillStartWorldTime = 0.0;
   551→
   552→	UE_LOG(LogWjWorldAbilities, Log, TEXT("UGA_SpawnBrick: 충전 리필 중지 (충전 완료)"));
