   555→void UGA_SpawnBrick::OnSpawnBrickChargesChanged(const FOnAttributeChangeData& Data)
   556→{
   557→	UAbilitySystemComponent* ASC = GetAbilitySystemComponentFromActorInfo();
   558→	if (!ASC)
   559→	{
   560→		return;
   561→	}
   562→
   563→	// 리필로 충전이 증가했으면 리필 시작 시각 갱신 (다음 리필까지의 남은 시간 계산용)
   564→	if (Data.NewValue > Data.OldValue && RefillEffectHandle.IsValid())
   565→	{
   566→		if (UWorld* World = GetWorld())
   567→		{
   568→			RefillStartWorldTime = World->GetTimeSeconds();
   569→		}
   570→	}
   571→
   572→	// 서버에서만 리필 관리
   573→	if (!CurrentActorInfo || !CurrentActorInfo->IsNetAuthority())
   574→	{
   575→		return;
   576→	}
   577→
   578→	float MaxChargesValue = ASC->GetNumericAttribute(UWjWorldCharacterAttributeSet::GetMaxSpawnBrickChargesAttribute());
   579→
   580→	// 충전이 최대치에 도달하면 리필 GE 제거
   581→	if (Data.NewValue >= MaxChargesValue && RefillEffectHandle.IsValid())
   582→	{
   583→		StopChargeRefill();
   584→	}
   585→}
