   604→float UGA_SpawnBrick::GetChargeRefillTimeRemaining() const
   605→{
   606→	if (!RefillEffectHandle.IsValid() || RefillStartWorldTime <= 0.0)
   607→	{
   608→		return 0.f;
   609→	}
   610→
   611→	const UWorld* World = GetWorld();
   612→	if (!World)
   613→	{
   614→		return 0.f;
   615→	}
   616→
   617→	double Elapsed = World->GetTimeSeconds() - RefillStartWorldTime;
   618→	float Remaining = ChargeRefillInterval - static_cast<float>(Elapsed);
   619→	return FMath::Max(Remaining, 0.f);
   620→}
