   114→bool FWjWorldWallLayoutConverter::ValidateWallLayout(
   115→	const TArray<TArray<int32>>& WallLayout,
   116→	FText& OutErrorMessage)
   117→{
   118→	if (WallLayout.Num() == 0)
   119→	{
   120→		OutErrorMessage = FText::FromString(TEXT("레이아웃이 비어있습니다."));
   121→		return false;
   122→	}
   123→
   124→	// 모든 행의 열 수가 동일한지 확인
   125→	const int32 ExpectedCols = WallLayout[0].Num();
   126→	for (int32 Row = 1; Row < WallLayout.Num(); ++Row)
   127→	{
   128→		if (WallLayout[Row].Num() != ExpectedCols)
   129→		{
   130→			OutErrorMessage = FText::FromString(TEXT("행마다 열 수가 일치하지 않습니다."));
   131→			return false;
   132→		}
   133→	}
   134→
   135→	// 1. 경계에서 Flood Fill로 외부 영역 마킹
   136→	TSet<FIntPoint> ExteriorCells;
   137→	MarkExteriorCells(WallLayout, ExteriorCells);
   138→
   139→	// 2. 외부 영역이 아닌 내부 빈 셀 찾기
   140→	int32 InteriorX = -1, InteriorY = -1;
   141→	bool bFoundInterior = FindInteriorEmptyCell(WallLayout, ExteriorCells, InteriorX, InteriorY);
   142→
   143→	if (!bFoundInterior)
   144→	{
   145→		// 내부 빈 공간이 없음 - 모든 빈 셀이 외부(경계에 연결됨)이거나 빈 셀이 없음
   146→		OutErrorMessage = FText::FromString(TEXT("벽으로 둘러싸인 내부 공간이 없습니다. 벽이 완전히 닫힌 형태로 플레이 영역을 만들어주세요."));
   147→		return false;
   148→	}
   149→
   150→	OutErrorMessage = FText::FromString(TEXT("유효한 레이아웃입니다."));
   151→	return true;
   152→}
