   154→bool FWjWorldWallLayoutConverter::SaveWallLayoutToFile(
   155→	const TArray<TArray<int32>>& WallLayout,
   156→	const FString& FilePath)
   157→{
   158→	FString CSVContent = WallLayoutToCSVString(WallLayout);
   159→
   160→	if (!FFileHelper::SaveStringToFile(CSVContent, *FilePath, FFileHelper::EEncodingOptions::ForceUTF8WithoutBOM))
   161→	{
   162→		UE_LOG(LogWjWorldPlacement, Error, TEXT("WallLayoutConverter: Failed to save file to %s"), *FilePath);
   163→		return false;
   164→	}
   165→
   166→	UE_LOG(LogWjWorldPlacement, Log, TEXT("WallLayoutConverter: Saved wall layout to %s"), *FilePath);
   167→	return true;
   168→}
