   170→void FWjWorldWallLayoutConverter::MarkExteriorCells(
   171→	const TArray<TArray<int32>>& WallLayout,
   172→	TSet<FIntPoint>& OutExteriorCells)
   173→{
   174→	OutExteriorCells.Empty();
   175→
   176→	const int32 Rows = WallLayout.Num();
   177→	if (Rows == 0) return;
   178→
   179→	const int32 Cols = WallLayout[0].Num();
   180→	if (Cols == 0) return;
   181→
   182→	const TArray<FIntPoint> Directions = {
   183→		{ 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 }
   184→	};
   185→
   186→	TQueue<FIntPoint> Queue;
   187→
   188→	// 경계(가장자리)에 있는 모든 빈 셀을 시작점으로 추가
   189→	// 상단/하단 행
   190→	for (int32 X = 0; X < Cols; ++X)
   191→	{
   192→		if (WallLayout[0][X] == WallCell_Empty)
   193→		{
   194→			FIntPoint Pt(X, 0);
   195→			if (!OutExteriorCells.Contains(Pt))
   196→			{
   197→				OutExteriorCells.Add(Pt);
   198→				Queue.Enqueue(Pt);
   199→			}
   200→		}
   201→		if (WallLayout[Rows - 1][X] == WallCell_Empty)
   202→		{
   203→			FIntPoint Pt(X, Rows - 1);
   204→			if (!OutExteriorCells.Contains(Pt))
   205→			{
   206→				OutExteriorCells.Add(Pt);
   207→				Queue.Enqueue(Pt);
   208→			}
   209→		}
   210→	}
   211→
   212→	// 좌측/우측 열
   213→	for (int32 Y = 0; Y < Rows; ++Y)
   214→	{
   215→		if (WallLayout[Y][0] == WallCell_Empty)
   216→		{
   217→			FIntPoint Pt(0, Y);
   218→			if (!OutExteriorCells.Contains(Pt))
   219→			{
   220→				OutExteriorCells.Add(Pt);
   221→				Queue.Enqueue(Pt);
   222→			}
   223→		}
   224→		if (WallLayout[Y][Cols - 1] == WallCell_Empty)
   225→		{
   226→			FIntPoint Pt(Cols - 1, Y);
   227→			if (!OutExteriorCells.Contains(Pt))
   228→			{
   229→				OutExteriorCells.Add(Pt);
   230→				Queue.Enqueue(Pt);
   231→			}
   232→		}
   233→	}
   234→
   235→	// Flood Fill: 경계에서 연결된 모든 빈 셀을 외부로 마킹
   236→	while (!Queue.IsEmpty())
   237→	{
   238→		FIntPoint Current;
   239→		Queue.Dequeue(Current);
   240→
   241→		for (const FIntPoint& Dir : Directions)
   242→		{
   243→			const int32 NX = Current.X + Dir.X;
   244→			const int32 NY = Current.Y + Dir.Y;
   245→
   246→			// 범위 체크
   247→			if (NX < 0 || NX >= Cols || NY < 0 || NY >= Rows)
   248→				continue;
   249→
   250→			// 벽이면 통과 불가
   251→			if (WallLayout[NY][NX] >= WallCell_Wall)
   252→				continue;
   253→
   254→			FIntPoint Next(NX, NY);
   255→			if (!OutExteriorCells.Contains(Next))
   256→			{
   257→				OutExteriorCells.Add(Next);
   258→				Queue.Enqueue(Next);
   259→			}
   260→		}
   261→	}
   262→}
   263→
   264→bool FWjWorldWallLayoutConverter::FindInteriorEmptyCell(
   265→	const TArray<TArray<int32>>& WallLayout,
   266→	const TSet<FIntPoint>& ExteriorCells,
   267→	int32& OutX,
   268→	int32& OutY)
   269→{
   270→	for (int32 Y = 0; Y < WallLayout.Num(); ++Y)
   271→	{
   272→		for (int32 X = 0; X < WallLayout[Y].Num(); ++X)
   273→		{
   274→			// 빈 셀이면서 외부 영역이 아닌 경우 = 내부 영역
   275→			if (WallLayout[Y][X] == WallCell_Empty && !ExteriorCells.Contains(FIntPoint(X, Y)))
   276→			{
   277→				OutX = X;
   278→				OutY = Y;
   279→				return true;
   280→			}
   281→		}
   282→	}
   283→
   284→	return false;
   285→}
