    10→bool FWjWorldWallDescription::LoadWallLayoutFromFile()
    11→{
    12→    WallLayout.Empty();
    13→
    14→    if (WallLayoutFilePath.FilePath.IsEmpty())
    15→    {
    16→        UE_LOG(LogWjWorld, Warning, TEXT("WallLayoutFilePath is empty"));
    17→        return false;
    18→    }
    19→
    20→    FString FileContent;
    21→    FString FilePath = WallLayoutFilePath.FilePath;
    22→
    23→    // 에디터에서 설정한 절대 경로를 Content 상대 경로로 변환
    24→    FString ContentRelativePath;
    25→    int32 ContentIndex = FilePath.Find(TEXT("/Content/"), ESearchCase::IgnoreCase);
    26→    if (ContentIndex == INDEX_NONE)
    27→    {
    28→        ContentIndex = FilePath.Find(TEXT("\\Content\\"), ESearchCase::IgnoreCase);
    29→    }
    30→
    31→    if (ContentIndex != INDEX_NONE)
    32→    {
    33→        // "/Content/" 또는 "\\Content\\" 이후의 상대 경로 추출
    34→        ContentRelativePath = FilePath.RightChop(ContentIndex + 9);
    35→        ContentRelativePath = ContentRelativePath.Replace(TEXT("\\"), TEXT("/"));
    36→    }
    37→
    38→    // 1차 시도: Content 디렉토리 기준 경로
    39→    FString ResolvedPath = FPaths::ProjectContentDir() / ContentRelativePath;
    40→
    41→    if (!FFileHelper::LoadFileToString(FileContent, *ResolvedPath))
    42→    {
    43→        // 2차 시도: 원본 절대 경로 (에디터에서만 동작)
    44→        if (!FFileHelper::LoadFileToString(FileContent, *FilePath))
    45→        {
    46→            UE_LOG(LogWjWorld, Error, TEXT("Failed to load file. Tried paths:\n  1) %s\n  2) %s"), *ResolvedPath, *FilePath);
    47→            return false;
    48→        }
    49→    }
    50→
    51→    UE_LOG(LogWjWorld, Log, TEXT("Successfully loaded wall layout from: %s"), *ResolvedPath);
    52→
    53→    bool bParseResult = ParseWallLayout(FileContent);
    54→    if(!bParseResult)
    55→    {
    56→        bIsLayoutValid = false;
    57→        return false;
    58→	}
    59→
    60→    if(RowNum > 0 && ColumnNum > 0)
    61→    {
    62→		int32 StartX = -1, StartY = -1;
    63→        bIsLayoutValid = (FindStartingEmptyCell(StartX, StartY) && IsAreaEnclosedByWalls(StartX, StartY));
    64→    }
    65→    else
    66→    {
    67→        bIsLayoutValid = false;
    68→	}
    69→
    70→    return bIsLayoutValid;
    71→}
