   147→void UPlayerProfileWidget::PopulateLocalStats()
   148→{
   149→	if (!StatsContainer)
   150→	{
   151→		return;
   152→	}
   153→
   154→	StatsContainer->ClearChildren();
   155→
   156→	UGameInstance* GI = GetGameInstance();
   157→	if (!GI)
   158→	{
   159→		return;
   160→	}
   161→
   162→	UWjWorldStatsSubsystem* StatsSub = GI->GetSubsystem<UWjWorldStatsSubsystem>();
   163→	if (!StatsSub)
   164→	{
   165→		return;
   166→	}
   167→
   168→	const TArray<FMinigameStatDescriptor>& Descriptors = GetAllMinigameDescriptors();
   169→	for (const FMinigameStatDescriptor& Desc : Descriptors)
   170→	{
   171→		// 미니게임 이름 헤더
   172→		UTextBlock* HeaderText = NewObject<UTextBlock>(this);
   173→		HeaderText->SetText(FText::Format(
   174→			NSLOCTEXT("WjWorldProfile", "SectionHeader", "━━ {0} ━━"),
   175→			Desc.MinigameName));
   176→		FSlateFontInfo HeaderFont = HeaderText->GetFont();
   177→		HeaderFont.Size = 14;
   178→		HeaderText->SetFont(HeaderFont);
   179→		StatsContainer->AddChild(HeaderText);
   180→
   181→		// 스탯 값들
   182→		FString StatsLine;
   183→		for (int32 i = 0; i < Desc.Stats.Num(); ++i)
   184→		{
   185→			const FMinigameStatEntry& Entry = Desc.Stats[i];
   186→			int32 Value = StatsSub->GetLocalStat(Entry.StatName);
   187→
   188→			if (i > 0)
   189→			{
   190→				StatsLine += TEXT("  |  ");
   191→			}
   192→			StatsLine += FString::Printf(TEXT("%s: %d"), *Entry.DisplayName.ToString(), Value);
   193→		}
   194→
   195→		UTextBlock* StatsText = NewObject<UTextBlock>(this);
   196→		StatsText->SetText(FText::FromString(StatsLine));
   197→		StatsContainer->AddChild(StatsText);
   198→	}
   199→}
