   201→void UPlayerProfileWidget::PopulateUserStats(const FUniqueNetIdRepl& UserId)
   202→{
   203→	if (!StatsContainer)
   204→	{
   205→		return;
   206→	}
   207→
   208→	StatsContainer->ClearChildren();
   209→
   210→	UGameInstance* GI = GetGameInstance();
   211→	if (!GI)
   212→	{
   213→		return;
   214→	}
   215→
   216→	UWjWorldStatsSubsystem* StatsSub = GI->GetSubsystem<UWjWorldStatsSubsystem>();
   217→	if (!StatsSub)
   218→	{
   219→		return;
   220→	}
   221→
   222→	const TArray<FMinigameStatDescriptor>& Descriptors = GetAllMinigameDescriptors();
   223→	for (const FMinigameStatDescriptor& Desc : Descriptors)
   224→	{
   225→		// 미니게임 이름 헤더
   226→		UTextBlock* HeaderText = NewObject<UTextBlock>(this);
   227→		HeaderText->SetText(FText::Format(
   228→			NSLOCTEXT("WjWorldProfile", "SectionHeader", "━━ {0} ━━"),
   229→			Desc.MinigameName));
   230→		FSlateFontInfo HeaderFont = HeaderText->GetFont();
   231→		HeaderFont.Size = 14;
   232→		HeaderText->SetFont(HeaderFont);
   233→		StatsContainer->AddChild(HeaderText);
   234→
   235→		// 스탯 값들
   236→		FString StatsLine;
   237→		for (int32 i = 0; i < Desc.Stats.Num(); ++i)
   238→		{
   239→			const FMinigameStatEntry& Entry = Desc.Stats[i];
   240→			int32 Value = StatsSub->GetUserStat(UserId, Entry.StatName);
   241→
   242→			if (i > 0)
   243→			{
   244→				StatsLine += TEXT("  |  ");
   245→			}
   246→			StatsLine += FString::Printf(TEXT("%s: %d"), *Entry.DisplayName.ToString(), Value);
   247→		}
   248→
   249→		UTextBlock* StatsText = NewObject<UTextBlock>(this);
   250→		StatsText->SetText(FText::FromString(StatsLine));
   251→		StatsContainer->AddChild(StatsText);
   252→	}
   253→}
