    33→void UWjWorldStatsSubsystem::RequestCurrentStats()
    34→{
    35→#if WITH_STEAM
    36→	ISteamUserStats* SteamStats = ::SteamUserStats();
    37→	if (SteamStats)
    38→	{
    39→		// Steamworks v161: RequestCurrentStats()가 제거됨
    40→		// Steam 클라이언트가 자동으로 스탯을 동기화하므로 즉시 사용 가능
    41→		bLocalStatsLoaded = true;
    42→
    43→		// 로컬 캐시 업데이트
    44→		const TArray<FMinigameStatDescriptor>& Descriptors = GetAllMinigameDescriptors();
    45→		for (const FMinigameStatDescriptor& Desc : Descriptors)
    46→		{
    47→			for (const FMinigameStatEntry& Entry : Desc.Stats)
    48→			{
    49→				int32 Value = 0;
    50→				SteamStats->GetStat(TCHAR_TO_UTF8(*Entry.StatName.ToString()), &Value);
    51→				LocalStats.Add(Entry.StatName, Value);
    52→			}
    53→		}
    54→
    55→		OnLocalStatsReady.Broadcast();
    56→		UE_LOG(LogWjWorldStats, Log, TEXT("StatsSubsystem: Steam stats loaded (auto-synced by client)"));
    57→	}
    58→	else
    59→	{
    60→		// Steam 초기화 안 됨 - 폴백
    61→		LoadLocalStatsFromConfig();
    62→		OnLocalStatsReady.Broadcast();
    63→	}
    64→#else
    65→	LoadLocalStatsFromConfig();
    66→	OnLocalStatsReady.Broadcast();
    67→	UE_LOG(LogWjWorldStats, Log, TEXT("StatsSubsystem: Loaded local stats from config (non-Steam)"));
    68→#endif
    69→}
