    75→	if (SteamStats && bLocalStatsLoaded)
    76→	{
    77→		int32 Value = 0;
    78→		if (SteamStats->GetStat(TCHAR_TO_UTF8(*StatName.ToString()), &Value))
    79→		{
    80→			return Value;
