   124→void UWjWorldStatsSubsystem::RequestUserStats(const FUniqueNetIdRepl& UserId)
   125→{
   126→	if (!UserId.IsValid())
   127→	{
   128→		return;
   129→	}
   130→
   131→	FString UserIdStr = UserId.ToString();
   132→
   133→#if WITH_STEAM
   134→	ISteamUserStats* SteamStats = ::SteamUserStats();
   135→	if (SteamStats)
   136→	{
   137→		// FUniqueNetIdRepl에서 CSteamID 추출
   138→		uint64 SteamId64 = FCString::Atoi64(*UserIdStr);
   139→		CSteamID SteamId(SteamId64);
   140→		SteamAPICall_t hCall = SteamStats->RequestUserStats(SteamId);
   141→		UserStatsCallResult.Set(hCall, this, &UWjWorldStatsSubsystem::OnSteamUserStatsReceivedCallback);
   142→		UE_LOG(LogWjWorldStats, Log, TEXT("StatsSubsystem: Requested user stats for %s (SteamAPICall=%llu)"), *UserIdStr, hCall);
   143→		return;
   144→	}
   145→#endif
   146→
   147→	// 폴백: 타 유저 스탯은 불가능하므로 빈 데이터로 즉시 완료
   148→	UserStatsCache.FindOrAdd(UserIdStr);
   149→	ReadyUserIds.Add(UserIdStr);
   150→
   151→	FUniqueNetIdRepl UserIdCopy = UserId;
   152→	OnUserStatsReceived.Broadcast(UserIdCopy);
   153→}
