   155→int32 UWjWorldStatsSubsystem::GetUserStat(const FUniqueNetIdRepl& UserId, FName StatName) const
   156→{
   157→	if (!UserId.IsValid())
   158→	{
   159→		return 0;
   160→	}
   161→
   162→	FString UserIdStr = UserId.ToString();
   163→
   164→#if WITH_STEAM
   165→	ISteamUserStats* SteamStats = ::SteamUserStats();
   166→	if (SteamStats && ReadyUserIds.Contains(UserIdStr))
   167→	{
   168→		uint64 SteamId64 = FCString::Atoi64(*UserIdStr);
   169→		CSteamID SteamId(SteamId64);
   170→		int32 Value = 0;
   171→		if (SteamStats->GetUserStat(SteamId, TCHAR_TO_UTF8(*StatName.ToString()), &Value))
   172→		{
   173→			return Value;
   174→		}
   175→	}
   176→#endif
   177→
   178→	const TMap<FName, int32>* UserStats = UserStatsCache.Find(UserIdStr);
   179→	if (UserStats)
   180→	{
   181→		const int32* Found = UserStats->Find(StatName);
   182→		return Found ? *Found : 0;
   183→	}
   184→	return 0;
   185→}
