   196→void UWjWorldStatsSubsystem::SaveLocalStatsToConfig()
   197→{
   198→	for (const auto& Pair : LocalStats)
   199→	{
   200→		GConfig->SetInt(*StatsConfigSection, *Pair.Key.ToString(), Pair.Value, GGameIni);
   201→	}
   202→	GConfig->Flush(false, GGameIni);
