   380→	// 클릭된 버튼 찾기 (IsHovered + HasMouseCapture 조합으로 더 안정적으로 판별)
   381→	for (const auto& Pair : PlayerButtonToIDMap)
   382→	{
   383→		UButton* Btn = Pair.Key;
   384→		if (Btn && (Btn->IsHovered() || Btn->HasMouseCapture()))
   385→		{
   386→			UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Player button clicked - PlayerID: %d"), Pair.Value);
   387→			ShowPlayerProfile(Pair.Value);
   388→			return;
   389→		}
   390→	}
   391→
   392→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: OnAnyPlayerButtonClicked - Could not find clicked button"));
