    79→void AWjWorldCharacterPlay::OnEliminated()
    80→{
    81→	if (bIsEliminated)
    82→	{
    83→		return; // 이미 사망한 경우 무시
    84→	}
    85→
    86→	// Shield 버프 체크 (있으면 소모하고 제거 무시)
    87→	if (AbilitySystemComponent.IsValid() && AbilitySystemComponent->HasMatchingGameplayTag(WjWorldGameplayTag::Buff_Shield()))
    88→	{
    89→		AbilitySystemComponent->RemoveLooseGameplayTag(WjWorldGameplayTag::Buff_Shield());
    90→		UE_LOG(LogWjWorld, Log, TEXT("AWjWorldCharacterPlay::OnEliminated - Shield consumed, elimination prevented"));
    91→		return;
    92→	}
    93→
    94→	bIsEliminated = true;
    95→
    96→	// ASC에 State.Eliminated 태그 추가 → 어빌리티 활성화 차단
    97→	if (AbilitySystemComponent.IsValid())
    98→	{
    99→		AbilitySystemComponent->AddLooseGameplayTag(WjWorldGameplayTag::State_Eliminated());
   100→		AbilitySystemComponent->CancelAllAbilities();
   101→	}
   102→
   103→	// PlayerState 데이터 컴포넌트 업데이트는 각 GameRule에서 처리
   104→
   105→	HandleEliminationEffects();
   106→}
