   461→void UWjWorldGameRuleApproachingWall::ShrinkSafeZones(bool& bAnySafeZoneExist)
   462→{
   463→	FloodFillPoints.Empty();
   464→
   465→	for (auto Iter = CurrentSafeZonePoints.CreateIterator(); Iter; ++Iter)
   466→	{
   467→		FIntPoint& SafeZonePoint = *Iter;
   468→		TArray<FIntPoint> AdjacentPoints = {
   469→			FIntPoint(SafeZonePoint.X + 1, SafeZonePoint.Y),
   470→			FIntPoint(SafeZonePoint.X - 1, SafeZonePoint.Y),
   471→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y + 1),
   472→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y - 1)
   473→		};
   474→
   475→		for (const FIntPoint& AdjacentPoint : AdjacentPoints)
   476→		{
   477→			if (CurrentSafeZonePoints.Contains(AdjacentPoint) == false)
   478→			{
   479→				FloodFillPoints.Add(SafeZonePoint);
   480→				break;
   481→			}
   482→		}
   483→	}
   484→
   485→	for(const FIntPoint& PointToRemove : FloodFillPoints)
   486→	{
   487→		CurrentSafeZonePoints.Remove(PointToRemove);
   488→	}
   489→
   490→	bAnySafeZoneExist = CurrentSafeZonePoints.Num() > 1;
   491→}
