   359→bool UWjWorldPlacementComponent::LoadLayoutFromSlot(const FString& SlotName)
   360→{
   361→	UWorld* World = GetWorld();
   362→	if (!World)
   363→	{
   364→		return false;
   365→	}
   366→
   367→	// SaveGame 로드
   368→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   369→		UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   370→	);
   371→
   372→	if (!SaveGame)
   373→	{
   374→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Failed to load layout from '%s'"), *SlotName);
   375→		return false;
   376→	}
   377→
   378→	// 컨텍스트 검증 (다른 컨텍스트의 레이아웃 로드 방지)
   379→	if (SaveGame->SavedContext != EPlacementContext::None && SaveGame->SavedContext != CurrentContext)
   380→	{
   381→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Context mismatch - slot '%s' is for '%s', current context is '%s'"),
   382→			*SlotName, *GetPlacementContextName(SaveGame->SavedContext), *GetPlacementContextName(CurrentContext));
   383→		return false;
   384→	}
   385→
   386→	// DataProvider가 있으면 데이터 설정
   387→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   388→	if (DataProvider)
   389→	{
   390→		// 일괄 설정 (RespawnAllPlacedObjects가 한 번만 호출됨)
   391→		DataProvider->SetPlacedObjects(SaveGame->PlacedObjects);
   392→	}
   393→
   394→	LoadedSlotName = SlotName;
   395→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout loaded from '%s' (%d objects)"),
   396→		*SlotName, SaveGame->PlacedObjects.Num());
   397→	return true;
   398→}
