   193→void AWjWorldCharacterPlay::PossessedBy(AController* NewController)
   194→{
   195→	Super::PossessedBy(NewController);
   196→
   197→	APlayerState* WJPlayerState = GetPlayerState<AWjWorldPlayerStatePlay>();
   198→	IAbilitySystemInterface* AbilitySystemInterface = Cast<IAbilitySystemInterface>(WJPlayerState);
   199→	if (AbilitySystemInterface)
   200→	{
   201→		AbilitySystemComponent = Cast<UWjWorldAbilitySystemComponent>(AbilitySystemInterface->GetAbilitySystemComponent());
   202→		if (!ensureMsgf(AbilitySystemComponent.IsValid(), TEXT("AWjWorldCharacterPlay::PossessedBy - AbilitySystemComponent is invalid")))
   203→		{
   204→			return;
   205→		}
   206→		AbilitySystemComponent->InitAbilityActorInfo(WJPlayerState, this);
   207→		AbilitySystemComponent->SetOwnerActor(NewController);
   208→
   209→		// Confirm/Cancel InputID 설정
   210→		AbilitySystemComponent->GenericConfirmInputID = static_cast<int32>(EWjWorldAbilityInputID::Confirm);
   211→		AbilitySystemComponent->GenericCancelInputID = static_cast<int32>(EWjWorldAbilityInputID::Cancel);
   212→
   213→		FLoadSoftObjectPathAsyncDelegate SetupDataLoadDel;
   214→		SetupDataLoadDel.BindUObject(this, &ThisClass::OnSetupDataAssetLoaded);
   215→		SetupDataAsset.LoadAsync(SetupDataLoadDel);
   216→	}
   217→
   218→	// 코스메틱 로드아웃 설정 (서버에서)
   219→	if (HasAuthority())
   220→	{
   221→		if (UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>())
   222→		{
   223→			if (CosmeticComponent)
   224→			{
   225→				CosmeticComponent->SetCatalog(CosmeticSub->GetCatalog());
   226→			}
   227→
   228→			if (AWjWorldPlayerStatePlay* PS = GetPlayerState<AWjWorldPlayerStatePlay>())
   229→			{
   230→				// 리스폰 시 PlayerState에 이미 로드아웃이 있으면 덮어쓰지 않음
   231→				// (호스트의 로드아웃으로 다른 플레이어 로드아웃을 덮어쓰는 버그 방지)
   232→				if (PS->GetCosmeticLoadout().Entries.IsEmpty())
   233→				{
   234→					// 최초 스폰: 로컬 서브시스템에서 로드아웃 가져옴 (서버 자신의 캐릭터만 해당)
   235→					APlayerController* PC = Cast<APlayerController>(NewController);
   236→					if (PC && PC->IsLocalController())
   237→					{
   238→						PS->SetCosmeticLoadout(CosmeticSub->GetLoadout());
   239→					}
   240→				}
   241→				// 서버에서도 Pawn 설정 알림 (기존 로드아웃 적용)
   242→				PS->OnPawnSet(nullptr, this);
   243→			}
   244→		}
   245→	}
   246→}
