    53→void UGA_SpawnBrick::OnGiveAbility(const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilitySpec& Spec)
    54→{
    55→	Super::OnGiveAbility(ActorInfo, Spec);
    56→
    57→	UAbilitySystemComponent* ASC = ActorInfo->AbilitySystemComponent.Get();
    58→	if (!ASC)
    59→	{
    60→		return;
    61→	}
    62→
    63→	// 서버에서 어트리뷰트 초기값 설정
    64→	if (ActorInfo->IsNetAuthority())
    65→	{
    66→		ASC->SetNumericAttributeBase(UWjWorldCharacterAttributeSet::GetMaxSpawnBrickChargesAttribute(), static_cast<float>(MaxCharges));
    67→		ASC->SetNumericAttributeBase(UWjWorldCharacterAttributeSet::GetSpawnBrickChargesAttribute(), static_cast<float>(MaxCharges));
    68→	}
    69→
    70→	// 리필 GE 오브젝트 생성
    71→	CreateRefillEffect();
    72→
    73→	// SpawnBrickCharges 변경 델리게이트 등록
    74→	ChargesChangedDelegateHandle = ASC->GetGameplayAttributeValueChangeDelegate(
    75→		UWjWorldCharacterAttributeSet::GetSpawnBrickChargesAttribute()
    76→	).AddUObject(this, &UGA_SpawnBrick::OnSpawnBrickChargesChanged);
    77→}
