    79→void UGA_SpawnBrick::OnRemoveAbility(const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilitySpec& Spec)
    80→{
    81→	StopChargeRefill();
    82→
    83→	// 델리게이트 해제
    84→	if (ChargesChangedDelegateHandle.IsValid())
    85→	{
    86→		UAbilitySystemComponent* ASC = ActorInfo->AbilitySystemComponent.Get();
    87→		if (ASC)
    88→		{
    89→			ASC->GetGameplayAttributeValueChangeDelegate(
    90→				UWjWorldCharacterAttributeSet::GetSpawnBrickChargesAttribute()
    91→			).Remove(ChargesChangedDelegateHandle);
    92→		}
    93→		ChargesChangedDelegateHandle.Reset();
    94→	}
    95→
    96→	Super::OnRemoveAbility(ActorInfo, Spec);
    97→}
