   120→void UGA_SpawnBrick::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, const FGameplayEventData* TriggerEventData)
   121→{
   122→	Super::ActivateAbility(Handle, ActorInfo, ActivationInfo, TriggerEventData);
   123→
   124→	// WallDesc 캐시
   125→	UWorld* World = GetWorld();
   126→	AWjWorldGameModePlay* GameModePlay = World ? World->GetAuthGameMode<AWjWorldGameModePlay>() : nullptr;
   127→	if (GameModePlay)
   128→	{
   129→		UWjWorldGameRuleApproachingWall* GameRule = GameModePlay->GetCurrentGameRule<UWjWorldGameRuleApproachingWall>();
   130→		if (GameRule)
   131→		{
   132→			CachedWallDesc = GameRule->GetWallDesc();
   133→		}
   134→	}
   135→
   136→	// 클라이언트에서는 GameMode에 접근 불가하므로 GameState의 GameData에서 WallName을 가져와 로드
   137→	if (CachedWallDesc.BrickSize.IsZero() || CachedWallDesc.ColumnNum == 0)
   138→	{
   139→		FString WallNameToLoad;
   140→
   141→		// GameState에서 현재 Wall 이름 가져오기
   142→		if (World)
   143→		{
   144→			if (AWjWorldGameStatePlay* GameState = World->GetGameState<AWjWorldGameStatePlay>())
   145→			{
   146→				if (UApproachingWallGameDataComponent* GameData = GameState->GetGameData<UApproachingWallGameDataComponent>())
   147→				{
   148→					WallNameToLoad = GameData->GetCurrentWallName();
   149→				}
   150→			}
   151→		}
   152→
   153→		const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   154→		if (DevSettings && !DevSettings->WallDescriptionAsset.IsNull())
   155→		{
   156→			UWjWorldWallDescriptionDataAsset* WallDescAsset = DevSettings->WallDescriptionAsset.LoadSynchronous();
   157→			if (WallDescAsset)
   158→			{
   159→				// WallName으로 정확한 WallDescription 조회 (유저 레이아웃 포함)
   160→				if (!WallNameToLoad.IsEmpty() && WallDescAsset->GetWallDescriptionByNameIncludingUser(WallNameToLoad, CachedWallDesc))
   161→				{
   162→					if (CachedWallDesc.IsLayoutEmpty())
   163→					{
   164→						CachedWallDesc.LoadWallLayoutFromFile();
   165→					}
   166→					UE_LOG(LogWjWorldAbilities, Log, TEXT("GA_SpawnBrick: Loaded WallDesc '%s' from GameData"), *WallNameToLoad);
   167→				}
   168→				// WallName이 없으면 첫 번째 Description 사용 (폴백)
   169→				else if (WallDescAsset->WallDescriptions.Num() > 0)
   170→				{
   171→					CachedWallDesc = WallDescAsset->WallDescriptions[0];
   172→					if (CachedWallDesc.IsLayoutEmpty())
   173→					{
   174→						CachedWallDesc.LoadWallLayoutFromFile();
   175→					}
   176→					UE_LOG(LogWjWorldAbilities, Warning, TEXT("GA_SpawnBrick: WallName not found, using first WallDesc as fallback"));
   177→				}
   178→			}
   179→		}
   180→	}
   181→
   182→	// Preview는 로컬 클라이언트에서만 표시
   183→	if (ActorInfo->IsLocallyControlled())
   184→	{
   185→		SpawnPreviewActor();
   186→
   187→		// Preview 위치 업데이트 타이머 시작
   188→		if (World)
   189→		{
   190→			World->GetTimerManager().SetTimer(
   191→				PreviewUpdateTimerHandle,
   192→				this,
   193→				&UGA_SpawnBrick::UpdatePreviewLocation,
   194→				0.016f, // ~60fps
   195→				true
   196→			);
   197→		}
   198→
   199→		// 프롬프트 UI 표시
   200→		if (AWjWorldCharacterPlay* CharacterPlay = Cast<AWjWorldCharacterPlay>(GetAvatarActorFromActorInfo()))
   201→		{
   202→			CharacterPlay->ShowAbilityPrompt(
   203→				NSLOCTEXT("AbilityPrompt", "ConfirmKey", "좌클릭"),
   204→				NSLOCTEXT("AbilityPrompt", "CancelKey", "우클릭"),
   205→				GetPromptDescription()
   206→			);
   207→		}
   208→	}
   209→
   210→	// Confirm/Cancel 대기 Task
   211→	UAbilityTask_WaitConfirmCancel* WaitConfirmCancelTask = UAbilityTask_WaitConfirmCancel::WaitConfirmCancel(this);
   212→	if (WaitConfirmCancelTask)
   213→	{
   214→		WaitConfirmCancelTask->OnConfirm.AddDynamic(this, &UGA_SpawnBrick::OnConfirmCallback);
   215→		WaitConfirmCancelTask->OnCancel.AddDynamic(this, &UGA_SpawnBrick::OnCancelCallback);
   216→		WaitConfirmCancelTask->ReadyForActivation();
   217→	}
   218→}
