   269→FVector UGA_SpawnBrick::CalculatePreviewLocation() const
   270→{
   271→	AActor* AvatarActor = GetAvatarActorFromActorInfo();
   272→	if (!AvatarActor) return FVector::ZeroVector;
   273→
   274→	FVector AvatarLocation = AvatarActor->GetActorLocation();
   275→	FRotator AvatarRotation = AvatarActor->GetActorRotation();
   276→
   277→	// Yaw를 45도 단위로 나눠서 4방향으로 스냅
   278→	float NormalizedYaw = FRotator::NormalizeAxis(AvatarRotation.Yaw);
   279→	FVector DirectionOffset = FVector::ZeroVector;
   280→
   281→	if (NormalizedYaw >= -45.0f && NormalizedYaw < 45.0f)
   282→	{
   283→		DirectionOffset.X = CachedWallDesc.BrickSize.X;
   284→	}
   285→	else if (NormalizedYaw >= 45.0f && NormalizedYaw < 135.0f)
   286→	{
   287→		DirectionOffset.Y = CachedWallDesc.BrickSize.Y;
   288→	}
   289→	else if (NormalizedYaw >= -135.0f && NormalizedYaw < -45.0f)
   290→	{
   291→		DirectionOffset.Y = -CachedWallDesc.BrickSize.Y;
   292→	}
   293→	else
   294→	{
   295→		DirectionOffset.X = -CachedWallDesc.BrickSize.X;
   296→	}
   297→
   298→	FVector PreviewPosition = AvatarLocation + DirectionOffset;
   299→
   300→	// 그리드에 스냅
   301→	FIntPoint GridIndex = UWjWorldBrickSpawner::CalculateBrickGridIndex(
   302→		PreviewPosition,
   303→		CachedWallDesc.ColumnNum,
   304→		CachedWallDesc.RowNum,
   305→		CachedWallDesc.CenterOffset,
   306→		CachedWallDesc.BrickSize
   307→	);
   308→
   309→	return UWjWorldBrickSpawner::CalculateBrickPosition(
   310→		GridIndex.X,
   311→		GridIndex.Y,
   312→		CachedWallDesc.ColumnNum,
   313→		CachedWallDesc.RowNum,
   314→		CachedWallDesc.CenterOffset,
   315→		CachedWallDesc.BrickSize
   316→	);
   317→}
