   319→bool UGA_SpawnBrick::CheckPreviewValid() const
   320→{
   321→	FVector PreviewLocation = CalculatePreviewLocation();
   322→
   323→	// 그리드 범위 체크
   324→	FIntPoint GridIndex = UWjWorldBrickSpawner::CalculateBrickGridIndex(
   325→		PreviewLocation,
   326→		CachedWallDesc.ColumnNum,
   327→		CachedWallDesc.RowNum,
   328→		CachedWallDesc.CenterOffset,
   329→		CachedWallDesc.BrickSize
   330→	);
   331→
   332→	if (GridIndex.X < 0 || GridIndex.X >= CachedWallDesc.ColumnNum ||
   333→		GridIndex.Y < 0 || GridIndex.Y >= CachedWallDesc.RowNum)
   334→	{
   335→		return false;
   336→	}
   337→
   338→	// 이미 벽돌이 있는 위치인지 오버랩 체크
   339→	UWorld* World = GetWorld();
   340→	if (!World) return false;
   341→
   342→	FVector HalfSize = CachedWallDesc.BrickSize * 0.3f;
   343→	TArray<FOverlapResult> Overlaps;
   344→	FCollisionShape CollisionShape = FCollisionShape::MakeBox(HalfSize);
   345→
   346→	if (World->OverlapMultiByObjectType(
   347→		Overlaps,
   348→		PreviewLocation,
   349→		FQuat::Identity,
   350→		FCollisionObjectQueryParams::AllObjects,
   351→		CollisionShape))
   352→	{
   353→		for (const FOverlapResult& Overlap : Overlaps)
   354→		{
   355→			if (Cast<AWjWorldBrickActor>(Overlap.GetActor()))
   356→			{
   357→				return false;
   358→			}
   359→		}
   360→	}
   361→
   362→	// 서버에서는 안전 구역 범위 내인지 체크
   363→	if (HasAuthority(&CurrentActivationInfo))
   364→	{
   365→		AWjWorldGameModePlay* GameModePlay = World->GetAuthGameMode<AWjWorldGameModePlay>();
   366→		if (GameModePlay)
   367→		{
   368→			UWjWorldGameRuleApproachingWall* GameRule = GameModePlay->GetCurrentGameRule<UWjWorldGameRuleApproachingWall>();
   369→			if (GameRule)
   370→			{
   371→				const TSet<FIntPoint>& SafeZonePoints = GameRule->GetCurrentSafeZonePoints();
   372→				if (!SafeZonePoints.Contains(GridIndex))
   373→				{
   374→					return false;
   375→				}
   376→			}
   377→		}
   378→	}
   379→
   380→	return true;
   381→}
