   196→	}
   197→
   198→	// 남은 플레이어 수 확인하여 승리 조건 체크
   199→	if (bIsGameStarted && CheckWinCondition())
   200→	{
   201→		// 마지막 생존자를 승자로 설정
   202→		if (AlivePlayerCount == 1 && AlivePlayers.Num() > 0)
   203→		{
   204→			for (const auto& AlivePlayer : AlivePlayers)
   205→			{
   206→				if (AlivePlayer.IsValid())
   207→				{
   208→					WinnerPlayer = AlivePlayer;
   209→					break;
   210→				}
   211→			}
   212→		}
   213→		bGameOverConditionMet = true;
   214→		OnGameEnd();
   215→	}
   216→}
   217→
   218→void UWjWorldGameRuleApproachingWall::OnPlayerEliminated(AWjWorldCharacterPlay* EliminatedCharacter)
   219→{
   220→	if (!HasAuthority() || !EliminatedCharacter) return;
   221→
   222→	// 이미 제거된 캐릭터면 무시
   223→	if (EliminatedCharacter->IsEliminated()) return;
   224→
   225→	// 공격자가 있으면 킬 스탯 기록
   226→	AWjWorldCharacterPlay* Attacker = EliminatedCharacter->GetLastAttacker();
   227→	if (Attacker && !Attacker->IsEliminated())
   228→	{
   229→		AWjWorldPlayerStatePlay* AttackerPS = Attacker->GetPlayerState<AWjWorldPlayerStatePlay>();
   230→		if (AttackerPS)
   231→		{
   232→			RecordKillStat(AttackerPS);
   233→			UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerEliminated - Kill recorded for %s"),
   234→				*AttackerPS->GetPlayerName());
   235→		}
   236→	}
   237→
   238→	// 캐릭터 사망 처리
   239→	EliminatedCharacter->OnEliminated();
   240→
   241→	// PlayerState 가져오기 + AW PlayerData 업데이트
   242→	AWjWorldPlayerStatePlay* PlayerState = EliminatedCharacter->GetPlayerState<AWjWorldPlayerStatePlay>();
   243→	if (PlayerState)
   244→	{
   245→		if (UApproachingWallPlayerDataComponent* PlayerData = PlayerState->GetGameData<UApproachingWallPlayerDataComponent>())
   246→		{
   247→			PlayerData->OnEliminated();
   248→		}
   249→
   250→		// 생존자 목록에서 제거
   251→		if (AlivePlayers.Remove(PlayerState) > 0)
   252→		{
   253→			AlivePlayerCount--;
   254→		}
   255→
   256→		UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerEliminated - Player: %s eliminated. Alive: %d"),
   257→			*PlayerState->GetPlayerName(), AlivePlayerCount);
   258→	}
   259→
   260→	UpdateGameData();
   261→
   262→	// 엣지 케이스: 동시에 모두 제거된 경우 (AlivePlayerCount == 0)
   263→	if (AlivePlayerCount == 0)
   264→	{
   265→		UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerEliminated - All players eliminated simultaneously (Draw)"));
   266→		bGameOverConditionMet = true;
   267→		WinnerPlayer = nullptr; // 무승부
   268→		OnGameEnd();
   269→		return;
   270→	}
   271→
   272→	// 승리 조건 체크
   273→	if (bIsGameStarted && CheckWinCondition())
   274→	{
   275→		bGameOverConditionMet = true;
   276→
   277→		// 마지막 생존자를 승자로 설정
   278→		if (AlivePlayerCount == 1 && AlivePlayers.Num() > 0)
   279→		{
   280→			for (const auto& AlivePlayer : AlivePlayers)
   281→			{
   282→				if (AlivePlayer.IsValid())
   283→				{
   284→					WinnerPlayer = AlivePlayer;
   285→					break;
   286→				}
   287→			}
   288→		}
   289→
   290→		UE_LOG(LogWjWorld, Log, TEXT("Win condition met! Winner: %s"),
   291→			WinnerPlayer.IsValid() ? *WinnerPlayer->GetPlayerName() : TEXT("None"));
   292→
   293→		OnGameEnd();
   294→	}
   295→}
   296→
   297→bool UWjWorldGameRuleApproachingWall::CheckWinCondition() const
   298→{
   299→	// 게임이 시작되지 않았으면 승리 조건 미충족
   300→	if (!bIsGameStarted) return false;
   301→
   302→	// 생존자가 1명 이하면 게임 종료
   303→	return AlivePlayerCount <= 1;
   304→}
   305→
   306→AWjWorldPlayerStatePlay* UWjWorldGameRuleApproachingWall::GetWinner() const
   307→{
   308→	return WinnerPlayer.Get();
   309→}
   310→
   311→void UWjWorldGameRuleApproachingWall::TickGameRule(float DeltaTime)
   312→{
   313→	if (!HasAuthority()) return;
   314→	if (!bGameStartInternalProcessDone) return;
   315→
   316→	TimeSinceLastBrickMoveSignal += DeltaTime;
   317→
   318→	if (TimeSinceLastBrickMoveSignal >= BrickMoveSignalInterval
   319→		&& bGameOverConditionMet == false)
   320→	{
   321→		// 오차 누적 방지
   322→		TimeSinceLastBrickMoveSignal -= BrickMoveSignalInterval;
   323→
   324→		++BrickMoveSignalCount;
   325→
   326→		bool bAnySafeZoneExist = false;
   327→		ShrinkSafeZones(bAnySafeZoneExist);
   328→
   329→		if (bAnySafeZoneExist)
   330→		{
   331→			if (WallManager)
   332→			{
   333→				WallManager->WallMoveStart(UWjWorldWallManager::GetBrickMovementAllowedTime(BrickMoveSignalCount));
   334→			}
   335→
   336→			GameLevelUp(BrickMoveSignalCount);
   337→			UpdateGameData();
   338→
   339→			if (PredictNextLevelIsLast())
   340→			{
   341→				OnGameEndPredict(BrickMoveSignalInterval);
   342→			}
   343→		}
   344→		else
   345→		{
   346→			bGameOverConditionMet = true;
   347→			UE_LOG(LogWjWorld, Log, TEXT("No Safe Zone Exist. Game Over Condition Met."));
   348→
   349→			// 안전 구역이 없어져서 게임이 끝날 때, 마지막 생존자가 승자
   350→			if (AlivePlayerCount == 1 && AlivePlayers.Num() > 0)
   351→			{
   352→				for (const auto& AlivePlayer : AlivePlayers)
   353→				{
   354→					if (AlivePlayer.IsValid())
   355→					{
   356→						WinnerPlayer = AlivePlayer;
   357→						break;
   358→					}
   359→				}
   360→				UE_LOG(LogWjWorld, Log, TEXT("Last player standing wins: %s"),
   361→					WinnerPlayer.IsValid() ? *WinnerPlayer->GetPlayerName() : TEXT("None"));
   362→			}
   363→
   364→			OnGameEnd();
   365→		}
   366→	}
   367→
   368→	if (WallManager)
   369→	{
   370→		WallManager->Tick(DeltaTime);
   371→	}
   372→}
   373→
   374→void UWjWorldGameRuleApproachingWall::InternalGameReadyProcess()
   375→{
   376→	if (!HasAuthority()) return;
   377→
   378→	if (bIsWallSpawned && bIsGameReady)
   379→	{
   380→		UE_LOG(LogWjWorld, Log, TEXT("Ready Game after Wall Spawned"));
   381→
   382→		if (GetWorld())
   383→		{
   384→			int32 SafeZoneIndex = 0;
   385→			for (auto Iter = GetWorld()->GetPlayerControllerIterator(); Iter; ++Iter)
   386→			{
   387→				APlayerController* PC = Iter->Get();
   388→				if (PC)
   389→				{
   390→					PC->ClientMessage(TEXT("Game Ready! Wall has spawned."));
   391→					FVector SpawnLocation = SpawnSafeZones.IsValidIndex(SafeZoneIndex) ? SpawnSafeZones[SafeZoneIndex] : FVector::ZeroVector;
   392→					SafeZoneIndex++;
   393→					if (APawn* Pawn = PC->GetPawn())
   394→					{
   395→						Pawn->SetActorLocation(SpawnLocation);
   396→					}
   397→				}
   398→			}
   399→		}
   400→	}
   401→
   402→	InternalGameStartProcess();
   403→}
   404→
   405→void UWjWorldGameRuleApproachingWall::InternalGameStartProcess()
   406→{
   407→	if (!HasAuthority()) return;
   408→
   409→	if(bIsWallSpawned && bIsGameReady && bIsGameStarted && !bGameStartInternalProcessDone)
   410→	{
   411→		bGameStartInternalProcessDone = true;
   412→		TimeSinceLastBrickMoveSignal = 0.0f;
   413→		BrickMoveSignalCount = 0;
   414→
   415→		UE_LOG(LogWjWorld, Log, TEXT("Starting Game after Wall Spawned"));
   416→	}
   417→}
   418→
   419→void UWjWorldGameRuleApproachingWall::OnWallSpawnFinished(const TArray<FVector>& InSafeZones, const FWjWorldWallDescription& Desc)
   420→{
   421→	if (!HasAuthority()) return;
   422→
   423→	bIsWallSpawned = true;
   424→	SpawnSafeZones.Empty();
   425→	SpawnSafeZones.Append(InSafeZones);
   426→
   427→	WallDesc = Desc;
   428→
   429→	// GameDataComponent에 현재 Wall 이름 저장 (클라이언트 리플리케이션용)
   430→	if (AWjWorldGameStatePlay* GameState = GetGameStatePlay())
   431→	{
   432→		if (UApproachingWallGameDataComponent* GameData = GameState->GetGameData<UApproachingWallGameDataComponent>())
   433→		{
   434→			GameData->SetCurrentWallName(Desc.WallName);
   435→		}
   436→	}
   437→
   438→	InternalGameReadyProcess();
   439→
   440→	if (BrickSpawner)
   441→	{
   442→		CurrentSafeZonePoints.Empty();
   443→		CurrentSafeZonePoints.Append(BrickSpawner->GetStartSafeZonePoints());
   444→		BrickSpawner->OnWallSpawnFinished.RemoveAll(this);
   445→	}
   446→}
   447→
   448→void UWjWorldGameRuleApproachingWall::UpdateGameData()
   449→{
   450→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   451→	if (!GameState) return;
   452→
   453→	UApproachingWallGameDataComponent* GameData = GameState->GetGameData<UApproachingWallGameDataComponent>();
   454→	if (!GameData) return;
   455→
   456→	GameData->SetCurrentLevel(BrickMoveSignalCount);
   457→	GameData->SetAlivePlayerCount(AlivePlayerCount);
   458→	GameData->SetTotalPlayerCount(TotalPlayerCount);
   459→}
   460→
   461→void UWjWorldGameRuleApproachingWall::ShrinkSafeZones(bool& bAnySafeZoneExist)
   462→{
   463→	FloodFillPoints.Empty();
   464→
   465→	for (auto Iter = CurrentSafeZonePoints.CreateIterator(); Iter; ++Iter)
   466→	{
   467→		FIntPoint& SafeZonePoint = *Iter;
   468→		TArray<FIntPoint> AdjacentPoints = {
   469→			FIntPoint(SafeZonePoint.X + 1, SafeZonePoint.Y),
   470→			FIntPoint(SafeZonePoint.X - 1, SafeZonePoint.Y),
   471→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y + 1),
   472→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y - 1)
   473→		};
   474→
   475→		for (const FIntPoint& AdjacentPoint : AdjacentPoints)
   476→		{
   477→			if (CurrentSafeZonePoints.Contains(AdjacentPoint) == false)
   478→			{
   479→				FloodFillPoints.Add(SafeZonePoint);
   480→				break;
   481→			}
   482→		}
   483→	}
   484→
   485→	for(const FIntPoint& PointToRemove : FloodFillPoints)
   486→	{
   487→		CurrentSafeZonePoints.Remove(PointToRemove);
   488→	}
   489→
   490→	bAnySafeZoneExist = CurrentSafeZonePoints.Num() > 1;
   491→}
   492→
   493→bool UWjWorldGameRuleApproachingWall::PredictNextLevelIsLast()
   494→{
   495→	TSet<FIntPoint> SimulatedSafeZones = CurrentSafeZonePoints;
   496→	TSet<FIntPoint> SimulatedFloodFillPoints;
   497→
   498→	for (auto Iter = SimulatedSafeZones.CreateIterator(); Iter; ++Iter)
   499→	{
   500→		FIntPoint& SafeZonePoint = *Iter;
   501→		TArray<FIntPoint> AdjacentPoints = {
   502→			FIntPoint(SafeZonePoint.X + 1, SafeZonePoint.Y),
   503→			FIntPoint(SafeZonePoint.X - 1, SafeZonePoint.Y),
   504→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y + 1),
   505→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y - 1)
   506→		};
   507→
   508→		for (const FIntPoint& AdjacentPoint : AdjacentPoints)
   509→		{
   510→			if (SimulatedSafeZones.Contains(AdjacentPoint) == false)
   511→			{
   512→				SimulatedFloodFillPoints.Add(SafeZonePoint);
   513→				break;
   514→			}
   515→		}
   516→	}
   517→
   518→	for (const FIntPoint& PointToRemove : SimulatedFloodFillPoints)
   519→	{
   520→		SimulatedSafeZones.Remove(PointToRemove);
   521→	}
   522→
   523→	return SimulatedSafeZones.Num() <= 1;
   524→}
   525→
   526→void UWjWorldGameRuleApproachingWall::RecordKillStat(AWjWorldPlayerStatePlay* KillerPlayerState)
   527→{
   528→	if (!KillerPlayerState) return;
   529→
   530→	// 서버에서만 실행
   531→	if (!HasAuthority()) return;
   532→
   533→	// 킬러의 PlayerController를 통해 스탯 기록
   534→	APlayerController* KillerPC = Cast<APlayerController>(KillerPlayerState->GetOwner());
   535→	if (KillerPC && KillerPC->IsLocalController())
   536→	{
   537→		// 로컬 플레이어면 직접 기록
   538→		UWjWorldStatsSubsystem* Stats = GetWorld()->GetGameInstance()->GetSubsystem<UWjWorldStatsSubsystem>();
   539→		if (Stats)
   540→		{
   541→			Stats->IncrementLocalStat(WjWorldStats::ApproachingWall::Kills);
   542→			Stats->StoreStats();
   543→		}
   544→	}
   545→	// 원격 플레이어의 킬은 게임 종료 시 클라이언트에서 각자 처리하거나
   546→	// 별도 RPC로 처리해야 함 (현재는 로컬 플레이어만 즉시 기록)
   547→
   548→	UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::RecordKillStat - Recorded kill for %s"),
   549→		*KillerPlayerState->GetPlayerName());
   550→}
