   116→void AWjWorldCharacterPlay::HandleEliminationEffects()
   117→{
   118→	// 움직임 비활성화
   119→	if (UCharacterMovementComponent* MovementComp = GetCharacterMovement())
   120→	{
   121→		MovementComp->DisableMovement();
   122→		MovementComp->StopMovementImmediately();
   123→	}
   124→
   125→	// 입력 비활성화 + 관전 대상 전환 (로컬 컨트롤러에서만)
   126→	APlayerController* PC = Cast<APlayerController>(GetController());
   127→	if (PC)
   128→	{
   129→		DisableInput(PC);
   130→
   131→		if (PC->IsLocalController())
   132→		{
   133→			// 살아있는 다른 플레이어 찾아서 관전
   134→			AGameStateBase* GS = GetWorld()->GetGameState<AGameStateBase>();
   135→			if (GS)
   136→			{
   137→				for (APlayerState* PS : GS->PlayerArray)
   138→				{
   139→					if (!PS || PS == PC->PlayerState) continue;
   140→					APawn* OtherPawn = PS->GetPawn();
   141→					AWjWorldCharacterPlay* OtherChar = Cast<AWjWorldCharacterPlay>(OtherPawn);
   142→					if (OtherChar && !OtherChar->IsEliminated())
   143→					{
   144→						PC->SetViewTargetWithBlend(OtherChar, 0.5f);
   145→						UE_LOG(LogWjWorld, Log, TEXT("HandleEliminationEffects: Spectating %s"), *PS->GetPlayerName());
   146→						break;
   147→					}
   148→				}
   149→			}
   150→		}
   151→	}
   152→
   153→	// 1초 후 캐릭터 파괴
   154→	if (GetWorld())
   155→	{
   156→		FTimerHandle DestroyHandle;
   157→		GetWorld()->GetTimerManager().SetTimer(DestroyHandle, [this]()
   158→		{
   159→			Destroy();
   160→		}, 1.0f, false);
   161→	}
   162→}
   163→
   164→void AWjWorldCharacterPlay::OnRep_PlayerState()
   165→{
   166→	Super::OnRep_PlayerState();
   167→
   168→	// ASC 초기화 (CharacterPlay 전용)
   169→	APlayerState* WJPlayerState = GetPlayerState<AWjWorldPlayerStatePlay>();
   170→	IAbilitySystemInterface* AbilitySystemInterface = Cast<IAbilitySystemInterface>(WJPlayerState);
   171→	if (AbilitySystemInterface)
   172→	{
   173→		AbilitySystemComponent = Cast<UWjWorldAbilitySystemComponent>(AbilitySystemInterface->GetAbilitySystemComponent());
   174→		if (AbilitySystemComponent.IsValid())
   175→		{
   176→			// 클라이언트에서도 ActorInfo 초기화 필요 (어빌리티 입력 처리를 위해)
   177→			AbilitySystemComponent->InitAbilityActorInfo(WJPlayerState, this);
   178→
   179→			// Confirm/Cancel InputID 설정
   180→			AbilitySystemComponent->GenericConfirmInputID = static_cast<int32>(EWjWorldAbilityInputID::Confirm);
   181→			AbilitySystemComponent->GenericCancelInputID = static_cast<int32>(EWjWorldAbilityInputID::Cancel);
   182→
   183→			// 클라이언트 공통 초기화 (어빌리티 부여는 Initialize 내부에서 Authority 체크)
   184→			FLoadSoftObjectPathAsyncDelegate SetupDataLoadDel;
   185→			SetupDataLoadDel.BindUObject(this, &ThisClass::OnSetupDataAssetLoaded);
   186→			SetupDataAsset.LoadAsync(SetupDataLoadDel);
   187→		}
   188→	}
   189→
   190→	// 코스메틱은 Super::OnRep_PlayerState()에서 처리됨 (CharacterBase)
   191→}
   192→
   193→void AWjWorldCharacterPlay::PossessedBy(AController* NewController)
   194→{
   195→	Super::PossessedBy(NewController);
   196→
   197→	APlayerState* WJPlayerState = GetPlayerState<AWjWorldPlayerStatePlay>();
   198→	IAbilitySystemInterface* AbilitySystemInterface = Cast<IAbilitySystemInterface>(WJPlayerState);
   199→	if (AbilitySystemInterface)
   200→	{
   201→		AbilitySystemComponent = Cast<UWjWorldAbilitySystemComponent>(AbilitySystemInterface->GetAbilitySystemComponent());
   202→		if (!ensureMsgf(AbilitySystemComponent.IsValid(), TEXT("AWjWorldCharacterPlay::PossessedBy - AbilitySystemComponent is invalid")))
   203→		{
   204→			return;
   205→		}
   206→		AbilitySystemComponent->InitAbilityActorInfo(WJPlayerState, this);
   207→		AbilitySystemComponent->SetOwnerActor(NewController);
   208→
   209→		// Confirm/Cancel InputID 설정
   210→		AbilitySystemComponent->GenericConfirmInputID = static_cast<int32>(EWjWorldAbilityInputID::Confirm);
   211→		AbilitySystemComponent->GenericCancelInputID = static_cast<int32>(EWjWorldAbilityInputID::Cancel);
   212→
   213→		FLoadSoftObjectPathAsyncDelegate SetupDataLoadDel;
   214→		SetupDataLoadDel.BindUObject(this, &ThisClass::OnSetupDataAssetLoaded);
   215→		SetupDataAsset.LoadAsync(SetupDataLoadDel);
   216→	}
   217→
   218→	// 코스메틱 로드아웃 설정 (서버에서)
   219→	if (HasAuthority())
   220→	{
   221→		if (UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>())
   222→		{
   223→			if (CosmeticComponent)
   224→			{
   225→				CosmeticComponent->SetCatalog(CosmeticSub->GetCatalog());
   226→			}
   227→
   228→			if (AWjWorldPlayerStatePlay* PS = GetPlayerState<AWjWorldPlayerStatePlay>())
   229→			{
   230→				// 리스폰 시 PlayerState에 이미 로드아웃이 있으면 덮어쓰지 않음
   231→				// (호스트의 로드아웃으로 다른 플레이어 로드아웃을 덮어쓰는 버그 방지)
   232→				if (PS->GetCosmeticLoadout().Entries.IsEmpty())
   233→				{
   234→					// 최초 스폰: 로컬 서브시스템에서 로드아웃 가져옴 (서버 자신의 캐릭터만 해당)
   235→					APlayerController* PC = Cast<APlayerController>(NewController);
   236→					if (PC && PC->IsLocalController())
   237→					{
   238→						PS->SetCosmeticLoadout(CosmeticSub->GetLoadout());
   239→					}
   240→				}
   241→				// 서버에서도 Pawn 설정 알림 (기존 로드아웃 적용)
   242→				PS->OnPawnSet(nullptr, this);
   243→			}
   244→		}
   245→	}
   246→}
   247→
   248→void AWjWorldCharacterPlay::OnSetupDataAssetLoaded(const FSoftObjectPath& Path, UObject* Object)
