   410→void AWjWorldCharacterPlay::ServerSpawnBrickAtGridIndex_Implementation(int32 GridX, int32 GridY)
   411→{
   412→	UE_LOG(LogWjWorld, Log, TEXT("AWjWorldCharacterPlay::ServerSpawnBrickAtGridIndex - GridIndex: (%d, %d)"), GridX, GridY);
   413→
   414→	UWorld* World = GetWorld();
   415→	if (!World)
   416→	{
   417→		return;
   418→	}
   419→
   420→	// 서버에서 WallDesc 가져오기
   421→	FWjWorldWallDescription ServerWallDesc;
   422→	AWjWorldGameModePlay* GameModePlay = World->GetAuthGameMode<AWjWorldGameModePlay>();
   423→	if (GameModePlay)
   424→	{
   425→		UWjWorldGameRuleApproachingWall* GameRule = GameModePlay->GetCurrentGameRule<UWjWorldGameRuleApproachingWall>();
   426→		if (GameRule)
   427→		{
   428→			ServerWallDesc = GameRule->GetWallDesc();
   429→		}
   430→	}
   431→
   432→	// WallDesc가 유효하지 않으면 실패
   433→	if (ServerWallDesc.BrickSize.IsZero() || ServerWallDesc.ColumnNum == 0)
   434→	{
   435→		UE_LOG(LogWjWorld, Warning, TEXT("AWjWorldCharacterPlay::ServerSpawnBrickAtGridIndex - Invalid WallDesc"));
   436→		return;
   437→	}
   438→
   439→	// 그리드 범위 체크
   440→	if (GridX < 0 || GridX >= ServerWallDesc.ColumnNum ||
   441→		GridY < 0 || GridY >= ServerWallDesc.RowNum)
   442→	{
   443→		UE_LOG(LogWjWorld, Warning, TEXT("AWjWorldCharacterPlay::ServerSpawnBrickAtGridIndex - Invalid GridIndex (%d, %d) for grid %dx%d"),
   444→			GridX, GridY, ServerWallDesc.ColumnNum, ServerWallDesc.RowNum);
   445→		return;
   446→	}
   447→
   448→	// 충전 소모 (ASC에서)
   449→	if (AbilitySystemComponent.IsValid())
   450→	{
   451→		const UGameplayEffect* CostGE = UGE_SpawnBrickChargeCost::StaticClass()->GetDefaultObject<UGameplayEffect>();
   452→		if (CostGE)
   453→		{
   454→			FGameplayEffectContextHandle ContextHandle = AbilitySystemComponent->MakeEffectContext();
   455→			FGameplayEffectSpec Spec(CostGE, ContextHandle, 1.f);
   456→			AbilitySystemComponent->ApplyGameplayEffectSpecToSelf(Spec);
   457→		}
   458→	}
   459→
   460→	FIntPoint SpawnIndexPoint(GridX, GridY);
   461→	FVector SpawnPosition = UWjWorldBrickSpawner::CalculateBrickPosition(
   462→		GridX,
   463→		GridY,
   464→		ServerWallDesc.ColumnNum,
   465→		ServerWallDesc.RowNum,
   466→		ServerWallDesc.CenterOffset,
   467→		ServerWallDesc.BrickSize
   468→	);
   469→
   470→	FWjWorldBrickProperties BrickProperties;
   471→	BrickProperties.BrickType = FMath::RandBool() ? EWjWorldBrickType::Moving : EWjWorldBrickType::Destructible;
   472→	BrickProperties.BrickMoveType = EWjWorldBrickMoveType::Standard;
   473→	BrickProperties.Size = ServerWallDesc.BrickSize;
   474→	BrickProperties.Color = BrickProperties.GetColorWithBrickType();
   475→	BrickProperties.SpawnedGridPosition = SpawnIndexPoint;
   476→	BrickProperties.CenterOffset = ServerWallDesc.CenterOffset;
   477→	BrickProperties.ColumnNum = ServerWallDesc.ColumnNum;
   478→	BrickProperties.RowNum = ServerWallDesc.RowNum;
   479→
   480→	// Destructible 벽돌은 DeveloperSettings에서 MaxHP 설정
   481→	if (BrickProperties.BrickType == EWjWorldBrickType::Destructible)
   482→	{
   483→		BrickProperties.MaxHP = GetDefault<UWjWorldDeveloperSettings>()->DestructibleBrickDefaultHP;
   484→	}
   485→
   486→	UWjWorldBrickSpawner::SpawnBrickActor(World, BrickProperties, GridX, GridY);
   487→
   488→	// GameplayCue 실행 (사운드/VFX)
   489→	if (AbilitySystemComponent.IsValid())
   490→	{
   491→		FGameplayCueParameters CueParams;
   492→		CueParams.Location = SpawnPosition;
   493→		AbilitySystemComponent->ExecuteGameplayCue(WjWorldGameplayTag::GameplayCue_Ability_SpawnBrick(), CueParams);
   494→	}
   495→}
