   209→	// 등록된 모든 스탯 이름을 순회하여 로드
   210→	const TArray<FMinigameStatDescriptor>& Descriptors = GetAllMinigameDescriptors();
   211→	for (const FMinigameStatDescriptor& Desc : Descriptors)
   212→	{
   213→		for (const FMinigameStatEntry& Entry : Desc.Stats)
   214→		{
   215→			int32 Value = 0;
   216→			if (GConfig->GetInt(*StatsConfigSection, *Entry.StatName.ToString(), Value, GGameIni))
   217→			{
   218→				LocalStats.Add(Entry.StatName, Value);
   219→			}
   220→			else
   221→			{
