    13→
    14→UWjWorldBrickSpawner* UWjWorldBrickSpawner::CreateBrickSpawner(UObject* Outer, TSoftObjectPtr<UWjWorldWallDescriptionDataAsset> WallDescDataAsset)
    15→{
    16→	if (Outer)
    17→	{
    18→		UWjWorldBrickSpawner* BrickSpawner = NewObject<UWjWorldBrickSpawner>(Outer, UWjWorldBrickSpawner::StaticClass());
    19→		if (BrickSpawner)
    20→		{
    21→			BrickSpawner->WallDescriptionDataAsset = WallDescDataAsset;
    22→			BrickSpawner->LoadedWallDescriptionDataAsset = WallDescDataAsset.LoadSynchronous();
    23→			BrickSpawner->TileActorClass = GetDefault<UWjWorldDeveloperSettings>()->TileActorClass.LoadSynchronous();
    24→
    25→			if (!BrickSpawner->LoadedWallDescriptionDataAsset)
    26→			{
    27→				UE_LOG(LogWjWorld, Error, TEXT("Failed to load WallDescriptionDataAsset: %s"), *WallDescDataAsset.ToString());
    28→			}
    29→
    30→			return BrickSpawner;
    31→		}
    32→	}
    33→
    34→	return nullptr;
    35→}
    36→
    37→AWjWorldBrickActor* UWjWorldBrickSpawner::SpawnBrickActor(UWorld* World, const FWjWorldBrickProperties& BrickProperties, int32 ColumnIndex, int32 RowIndex)
    38→{
    39→	if (!World) return nullptr;
    40→
    41→	AWjWorldBrickActor* BrickActor = World->SpawnActorDeferred<AWjWorldBrickActor>(AWjWorldBrickActor::StaticClass(), FTransform());
    42→	if (BrickActor)
    43→	{
    44→		if (UWjWorldBrickComponent* BrickComponent = BrickActor->GetBrickComponent())
    45→		{
    46→			BrickComponent->InitializeBrick(BrickProperties);
    47→		}
    48→
    49→		FVector BrickPosition = CalculateBrickPosition(
    50→			ColumnIndex,
    51→			RowIndex,
    52→			BrickProperties.ColumnNum,
    53→			BrickProperties.RowNum,
    54→			BrickProperties.CenterOffset,
    55→			BrickProperties.Size);
    56→
    57→		BrickActor->FinishSpawning(FTransform(BrickPosition));
    58→	}
    59→
    60→	return BrickActor;
    61→}
    62→
    63→void UWjWorldBrickSpawner::SpawnBricksRandomMapAsync()
    64→{
    65→	FString RandomWallName = GenerateRandomWallName();
    66→	UE_LOG(LogWjWorld, Log, TEXT("Spawning Bricks from Random Wall Name: %s"), *RandomWallName);
    67→
    68→	SpawnBricksFromWallNameAsync(RandomWallName);
    69→}
    70→
    71→void UWjWorldBrickSpawner::SpawnBricksFromWallNameAsync(const FString& WallName)
    72→{
    73→	if (!LoadedWallDescriptionDataAsset) return;
    74→
    75→	// 내장 레이아웃 + 유저 레이아웃 모두 검색
    76→	if (!LoadedWallDescriptionDataAsset->GetWallDescriptionByNameIncludingUser(WallName, TargetDesc))
    77→	{
    78→		UE_LOG(LogWjWorld, Error, TEXT("Invalid Wall Desc Name : %s"), *WallName);
    79→		return;
    80→	}
    81→
    82→	SpawnBricksFromWallDescriptionAsync(TargetDesc);
    83→}
    84→
    85→FVector UWjWorldBrickSpawner::CalculateBrickPosition(int32 BrickColIndex, int32 BrickRowIndex, int32 ColNum, int32 RowNum, const FVector& WallOrigin, const FVector& BrickSize)
    86→{
    87→	// 그리드 중심 인덱스 (정중앙 기준)
    88→	const float CenterCol = (ColNum - 1) * 0.5f;
    89→	const float CenterRow = (RowNum - 1) * 0.5f;
    90→
    91→	// 중심으로부터의 오프셋 (그리드 좌표계)
    92→	const float ColOffset = BrickColIndex - CenterCol;
    93→	const float RowOffset = BrickRowIndex - CenterRow;
    94→
    95→	// 월드 오프셋 (BrickSize 반영)
    96→	const float WorldOffsetX = ColOffset * BrickSize.X;
    97→	const float WorldOffsetY = RowOffset * BrickSize.Y;
    98→
    99→	return WallOrigin + FVector(WorldOffsetX, WorldOffsetY, BrickSize.Z / 2.0);
   100→}
   101→
   102→FIntPoint UWjWorldBrickSpawner::CalculateBrickGridIndex(const FVector& WorldLocation, int32 ColNum, int32 RowNum, const FVector& WallOrigin, const FVector& BrickSize)
   103→{
   104→	// 그리드 중심 인덱스 (정중앙 기준)
   105→	const float CenterCol = (ColNum - 1) * 0.5f;
   106→	const float CenterRow = (RowNum - 1) * 0.5f;
   107→
   108→	// 월드 오프셋 계산
   109→	const float WorldOffsetX = WorldLocation.X - WallOrigin.X;
   110→	const float WorldOffsetY = WorldLocation.Y - WallOrigin.Y;
   111→
   112→	// 그리드 오프셋 계산
   113→	const float ColOffset = WorldOffsetX / BrickSize.X;
   114→	const float RowOffset = WorldOffsetY / BrickSize.Y;
   115→
   116→	// 그리드 인덱스 계산 (반올림하여 가장 가까운 셀로)
   117→	const int32 ColIndex = FMath::RoundToInt32(ColOffset + CenterCol);
   118→	const int32 RowIndex = FMath::RoundToInt32(RowOffset + CenterRow);
   119→
   120→	return FIntPoint(ColIndex, RowIndex);
   121→}
   122→
   123→const TArray<FIntPoint>& UWjWorldBrickSpawner::GetStartSafeZonePoints()
   124→{
   125→	return StartSafeZonePoints;
   126→}
   127→
   128→void UWjWorldBrickSpawner::Tick(float DeltaTime)
   129→{
   130→	UWorld* World = GetWorld();
   131→	if (World == nullptr) return;
   132→
   133→	bool bIsLayoutValid = TargetDesc.IsLayoutValid();
   134→	if (bIsLayoutValid == false)
   135→	{
   136→		UE_LOG(LogWjWorld, Error, TEXT("Wall Description Layout is Invalid"));
   137→		CurrentLoadingBrickColIndex = 0;
   138→		CurrentLoadingBrickRowIndex = 0;
   139→		SetTickable(false);
   140→		return;
   141→	}
   142→
   143→	int32 ProcessedCellsCount = 0;
   144→	bool bFinishedSpawning = false;
   145→
   146→	while (ProcessedCellsCount < CheckCellCountPerTick
   147→		&& bFinishedSpawning == false)
   148→	{
   149→		int32 BrickType = TargetDesc.WallLayout[CurrentLoadingBrickRowIndex][CurrentLoadingBrickColIndex];
   150→		++ProcessedCellsCount;
   151→
   152→		if (BrickType >= (int32)EWjWorldBrickType::Standard)
   153→		{
   154→			FWjWorldBrickProperties BrickProperties;
   155→			BrickProperties.BrickType = static_cast<EWjWorldBrickType>(BrickType);
   156→			BrickProperties.BrickMoveType = EWjWorldBrickMoveType::Standard;
   157→			BrickProperties.Size = TargetDesc.BrickSize;
   158→			BrickProperties.Color = FColor::White;
   159→			BrickProperties.SpawnedGridPosition = FIntPoint(CurrentLoadingBrickColIndex, CurrentLoadingBrickRowIndex);
   160→			BrickProperties.CenterOffset = TargetDesc.CenterOffset;
   161→			BrickProperties.ColumnNum = TargetDesc.ColumnNum;
   162→			BrickProperties.RowNum = TargetDesc.RowNum;
   163→
   164→			// Destructible 벽돌은 DeveloperSettings에서 MaxHP 설정
   165→			if (BrickProperties.BrickType == EWjWorldBrickType::Destructible)
   166→			{
   167→				BrickProperties.MaxHP = GetDefault<UWjWorldDeveloperSettings>()->DestructibleBrickDefaultHP;
   168→			}
   169→
   170→			SpawnBrickActor(World, BrickProperties, CurrentLoadingBrickColIndex, CurrentLoadingBrickRowIndex);
   171→		}
   172→		else if (BrickType < (int32)EWjWorldBrickType::Standard
   173→			&& TargetDesc.SafeZonesSet.Contains(FIntPoint(CurrentLoadingBrickColIndex, CurrentLoadingBrickRowIndex)))
   174→		{
   175→			FVector TilePosition = CalculateBrickPosition(
   176→				CurrentLoadingBrickColIndex,
   177→				CurrentLoadingBrickRowIndex,
   178→				TargetDesc.ColumnNum,
   179→				TargetDesc.RowNum,
   180→				TargetDesc.CenterOffset,
   181→				TargetDesc.BrickSize);
   182→
   183→			// 바둑판 패턴: (Column + Row) % 2로 검정/흰색 결정
   184→			const bool bIsWhiteTile = (CurrentLoadingBrickColIndex + CurrentLoadingBrickRowIndex) % 2 == 0;
   185→
   186→			// Deferred Spawn: InitializeTile 후 BeginPlay 호출
   187→			AWjWorldTileActor* TileActor = World->SpawnActorDeferred<AWjWorldTileActor>(
   188→				TileActorClass ? TileActorClass.Get() : AWjWorldTileActor::StaticClass(),
   189→				FTransform(TilePosition));
   190→
   191→			if (TileActor)
   192→			{
   193→				TileActor->InitializeTile(TargetDesc.BrickSize, TilePosition, bIsWhiteTile);
   194→				TileActor->FinishSpawning(FTransform(TilePosition));
   195→			}
   196→		}
   197→
   198→		CurrentLoadingBrickColIndex++;
   199→		if (TargetDesc.WallLayout[CurrentLoadingBrickRowIndex].IsValidIndex(CurrentLoadingBrickColIndex) == false)
   200→		{
   201→			CurrentLoadingBrickColIndex = 0;
   202→			CurrentLoadingBrickRowIndex++;
   203→
   204→			if (TargetDesc.WallLayout.IsValidIndex(CurrentLoadingBrickRowIndex) == false)
   205→			{
   206→				CurrentLoadingBrickColIndex = 0;
   207→				CurrentLoadingBrickRowIndex = 0;
   208→				bFinishedSpawning = true;
   209→				SetTickable(false);
   210→				UE_LOG(LogWjWorld, Log, TEXT("Finished Spawning All Bricks"));
   211→			}
   212→		}
   213→	}
   214→
   215→	if (bFinishedSpawning)
   216→	{
   217→		TArray<FIntPoint> RandomSafeZonePoints;
   218→		TargetDesc.GetRandomSafeZones(RandomSafeZonePoints);
   219→
   220→		StartSafeZonePoints = TargetDesc.SafeZones;
   221→
   222→		TArray<FVector> RandomSafeZoneLocations;
   223→		for(const FIntPoint& SafeZonePoint : RandomSafeZonePoints)
   224→		{
   225→			FVector SafeZoneLocation = CalculateBrickPosition(
   226→				SafeZonePoint.X,
   227→				SafeZonePoint.Y,
   228→				TargetDesc.ColumnNum,
   229→				TargetDesc.RowNum,
   230→				TargetDesc.CenterOffset,
   231→				TargetDesc.BrickSize);
   232→			RandomSafeZoneLocations.Add(SafeZoneLocation);
   233→		}
   234→
   235→		OnWallSpawnFinished.Broadcast(RandomSafeZoneLocations, TargetDesc);
   236→		TargetDesc.Reset();
   237→	}
   238→
   239→	UE_LOG(LogWjWorld, Warning,
   240→		TEXT("Tick Start: Row=%d Col=%d bTickable=%d"),
   241→		CurrentLoadingBrickRowIndex,
   242→		CurrentLoadingBrickColIndex,
   243→		bTickable);
   244→}
   245→
   246→UWorld* UWjWorldBrickSpawner::GetTickableGameObjectWorld() const
   247→{
   248→	if (GetOuter())
   249→	{
   250→		return GetOuter()->GetWorld();
   251→	}
   252→	return nullptr;
   253→}
   254→
