   220→void UGA_SpawnBrick::EndAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, bool bReplicateEndAbility, bool bWasCancelled)
   221→{
   222→	// 타이머 정리
   223→	if (UWorld* WorldPtr = GetWorld())
   224→	{
   225→		WorldPtr->GetTimerManager().ClearTimer(PreviewUpdateTimerHandle);
   226→	}
   227→
   228→	// Preview 정리
   229→	DestroyPreviewActor();
   230→
   231→	// 프롬프트 UI 숨김
   232→	if (ActorInfo && ActorInfo->IsLocallyControlled())
   233→	{
   234→		if (AWjWorldCharacterPlay* CharacterPlay = Cast<AWjWorldCharacterPlay>(GetAvatarActorFromActorInfo()))
   235→		{
   236→			CharacterPlay->HideAbilityPrompt();
   237→		}
   238→	}
   239→
   240→	Super::EndAbility(Handle, ActorInfo, ActivationInfo, bReplicateEndAbility, bWasCancelled);
   241→}
   242→
   243→void UGA_SpawnBrick::SpawnPreviewActor()
   244→{
   245→	if (PreviewActor) return;
   246→
   247→	UWorld* World = GetWorld();
   248→	if (!World) return;
   249→
   250→	FVector SpawnLocation = CalculatePreviewLocation();
   251→	PreviewActor = World->SpawnActor<AWjWorldBrickPreviewActor>(AWjWorldBrickPreviewActor::StaticClass(), SpawnLocation, FRotator::ZeroRotator);
   252→
   253→	if (PreviewActor)
   254→	{
   255→		PreviewActor->InitializePreview(CachedWallDesc.BrickSize);
   256→		PreviewActor->SetPreviewValid(CheckPreviewValid());
   257→	}
   258→}
   259→
   260→void UGA_SpawnBrick::DestroyPreviewActor()
   261→{
   262→	if (PreviewActor)
   263→	{
   264→		PreviewActor->Destroy();
   265→		PreviewActor = nullptr;
   266→	}
   267→}
