   269→FVector UGA_SpawnBrick::CalculatePreviewLocation() const
   270→{
   271→	AActor* AvatarActor = GetAvatarActorFromActorInfo();
   272→	if (!AvatarActor) return FVector::ZeroVector;
   273→
   274→	FVector AvatarLocation = AvatarActor->GetActorLocation();
   275→	FRotator AvatarRotation = AvatarActor->GetActorRotation();
   276→
   277→	// Yaw를 45도 단위로 나눠서 4방향으로 스냅
   278→	float NormalizedYaw = FRotator::NormalizeAxis(AvatarRotation.Yaw);
   279→	FVector DirectionOffset = FVector::ZeroVector;
   280→
   281→	if (NormalizedYaw >= -45.0f && NormalizedYaw < 45.0f)
   282→	{
   283→		DirectionOffset.X = CachedWallDesc.BrickSize.X;
   284→	}
   285→	else if (NormalizedYaw >= 45.0f && NormalizedYaw < 135.0f)
   286→	{
   287→		DirectionOffset.Y = CachedWallDesc.BrickSize.Y;
   288→	}
   289→	else if (NormalizedYaw >= -135.0f && NormalizedYaw < -45.0f)
   290→	{
   291→		DirectionOffset.Y = -CachedWallDesc.BrickSize.Y;
   292→	}
   293→	else
   294→	{
   295→		DirectionOffset.X = -CachedWallDesc.BrickSize.X;
   296→	}
   297→
   298→	FVector PreviewPosition = AvatarLocation + DirectionOffset;
   299→
   300→	// 그리드에 스냅
   301→	FIntPoint GridIndex = UWjWorldBrickSpawner::CalculateBrickGridIndex(
   302→		PreviewPosition,
   303→		CachedWallDesc.ColumnNum,
   304→		CachedWallDesc.RowNum,
   305→		CachedWallDesc.CenterOffset,
   306→		CachedWallDesc.BrickSize
   307→	);
   308→
   309→	return UWjWorldBrickSpawner::CalculateBrickPosition(
   310→		GridIndex.X,
   311→		GridIndex.Y,
   312→		CachedWallDesc.ColumnNum,
   313→		CachedWallDesc.RowNum,
   314→		CachedWallDesc.CenterOffset,
   315→		CachedWallDesc.BrickSize
   316→	);
   317→}
   318→
   319→bool UGA_SpawnBrick::CheckPreviewValid() const
   320→{
   321→	FVector PreviewLocation = CalculatePreviewLocation();
   322→
   323→	// 그리드 범위 체크
   324→	FIntPoint GridIndex = UWjWorldBrickSpawner::CalculateBrickGridIndex(
   325→		PreviewLocation,
   326→		CachedWallDesc.ColumnNum,
   327→		CachedWallDesc.RowNum,
   328→		CachedWallDesc.CenterOffset,
   329→		CachedWallDesc.BrickSize
   330→	);
   331→
   332→	if (GridIndex.X < 0 || GridIndex.X >= CachedWallDesc.ColumnNum ||
   333→		GridIndex.Y < 0 || GridIndex.Y >= CachedWallDesc.RowNum)
   334→	{
   335→		return false;
   336→	}
   337→
   338→	// 이미 벽돌이 있는 위치인지 오버랩 체크
   339→	UWorld* World = GetWorld();
   340→	if (!World) return false;
   341→
   342→	FVector HalfSize = CachedWallDesc.BrickSize * 0.3f;
   343→	TArray<FOverlapResult> Overlaps;
   344→	FCollisionShape CollisionShape = FCollisionShape::MakeBox(HalfSize);
   345→
   346→	if (World->OverlapMultiByObjectType(
   347→		Overlaps,
   348→		PreviewLocation,
   349→		FQuat::Identity,
   350→		FCollisionObjectQueryParams::AllObjects,
   351→		CollisionShape))
   352→	{
   353→		for (const FOverlapResult& Overlap : Overlaps)
   354→		{
   355→			if (Cast<AWjWorldBrickActor>(Overlap.GetActor()))
   356→			{
   357→				return false;
   358→			}
   359→		}
   360→	}
   361→
   362→	// 서버에서는 안전 구역 범위 내인지 체크
   363→	if (HasAuthority(&CurrentActivationInfo))
   364→	{
   365→		AWjWorldGameModePlay* GameModePlay = World->GetAuthGameMode<AWjWorldGameModePlay>();
   366→		if (GameModePlay)
   367→		{
   368→			UWjWorldGameRuleApproachingWall* GameRule = GameModePlay->GetCurrentGameRule<UWjWorldGameRuleApproachingWall>();
   369→			if (GameRule)
   370→			{
   371→				const TSet<FIntPoint>& SafeZonePoints = GameRule->GetCurrentSafeZonePoints();
   372→				if (!SafeZonePoints.Contains(GridIndex))
   373→				{
   374→					return false;
   375→				}
   376→			}
   377→		}
   378→	}
   379→
   380→	return true;
   381→}
   382→
   383→void UGA_SpawnBrick::OnConfirmCallback()
   384→{
   385→	UE_LOG(LogWjWorldAbilities, Log, TEXT("UGA_SpawnBrick::OnConfirmCallback - GridIndex: (%d, %d)"),
   386→		CachedPreviewGridIndex.X, CachedPreviewGridIndex.Y);
   387→
   388→	if (CheckPreviewValid() && CachedPreviewGridIndex.X >= 0 && CachedPreviewGridIndex.Y >= 0)
   389→	{
   390→		// Character를 통해 Server RPC 호출 (UObject에서는 Server RPC 동작 안 함)
   391→		AWjWorldCharacterPlay* CharacterPlay = Cast<AWjWorldCharacterPlay>(GetAvatarActorFromActorInfo());
   392→		if (CharacterPlay)
   393→		{
   394→			// 서버에서 직접 실행되는 경우 (Listen Server 호스트)
   395→			if (HasAuthority(&CurrentActivationInfo))
   396→			{
   397→				ApplyChargeCost();
   398→				CharacterPlay->ServerSpawnBrickAtGridIndex(CachedPreviewGridIndex.X, CachedPreviewGridIndex.Y);
   399→				StartChargeRefill();
   400→			}
   401→			// 클라이언트에서 서버로 RPC 호출
   402→			else if (CurrentActorInfo && CurrentActorInfo->IsLocallyControlled())
   403→			{
   404→				// 클라이언트에서는 충전 소모/리필이 서버에서 처리됨
   405→				CharacterPlay->ServerSpawnBrickAtGridIndex(CachedPreviewGridIndex.X, CachedPreviewGridIndex.Y);
   406→			}
   407→		}
   408→	}
   409→
   410→	EndAbility(CurrentSpecHandle, CurrentActorInfo, CurrentActivationInfo, true, false);
   411→}
   412→
   413→void UGA_SpawnBrick::OnCancelCallback()
   414→{
   415→	UE_LOG(LogWjWorldAbilities, Log, TEXT("UGA_SpawnBrick::OnCancelCallback"));
   416→	EndAbility(CurrentSpecHandle, CurrentActorInfo, CurrentActivationInfo, true, true);
   417→}
   418→
   419→void UGA_SpawnBrick::SpawnBrickAtPreviewLocation()
   420→{
   421→	// 더 이상 사용하지 않음 - ServerSpawnBrickAtGridIndex로 대체
   422→	FVector SpawnPosition = CalculatePreviewLocation();
   423→	FIntPoint SpawnIndexPoint = UWjWorldBrickSpawner::CalculateBrickGridIndex(
   424→		SpawnPosition,
   425→		CachedWallDesc.ColumnNum,
   426→		CachedWallDesc.RowNum,
   427→		CachedWallDesc.CenterOffset,
   428→		CachedWallDesc.BrickSize
   429→	);
   430→
   431→	FWjWorldBrickProperties BrickProperties;
   432→	BrickProperties.BrickType = FMath::RandBool() ? EWjWorldBrickType::Moving : EWjWorldBrickType::Destructible;
   433→	BrickProperties.BrickMoveType = EWjWorldBrickMoveType::Standard;
   434→	BrickProperties.Size = CachedWallDesc.BrickSize;
   435→	BrickProperties.Color = BrickProperties.GetColorWithBrickType();
   436→	BrickProperties.SpawnedGridPosition = SpawnIndexPoint;
   437→	BrickProperties.CenterOffset = CachedWallDesc.CenterOffset;
   438→	BrickProperties.ColumnNum = CachedWallDesc.ColumnNum;
   439→	BrickProperties.RowNum = CachedWallDesc.RowNum;
   440→
   441→	// Destructible 벽돌은 DeveloperSettings에서 MaxHP 설정
   442→	if (BrickProperties.BrickType == EWjWorldBrickType::Destructible)
   443→	{
   444→		BrickProperties.MaxHP = GetDefault<UWjWorldDeveloperSettings>()->DestructibleBrickDefaultHP;
   445→	}
   446→
   447→	UWjWorldBrickSpawner::SpawnBrickActor(GetWorld(), BrickProperties, SpawnIndexPoint.X, SpawnIndexPoint.Y);
   448→}
   449→
   450→void UGA_SpawnBrick::UpdatePreviewLocation()
   451→{
   452→	if (PreviewActor)
   453→	{
   454→		FVector NewLocation = CalculatePreviewLocation();
   455→		PreviewActor->UpdatePreviewLocation(NewLocation);
   456→		PreviewActor->SetPreviewValid(CheckPreviewValid());
   457→
   458→		// 클라이언트에서 GridIndex를 캐시 (Confirm 시 서버로 전달)
   459→		CachedPreviewGridIndex = UWjWorldBrickSpawner::CalculateBrickGridIndex(
   460→			NewLocation,
   461→			CachedWallDesc.ColumnNum,
   462→			CachedWallDesc.RowNum,
   463→			CachedWallDesc.CenterOffset,
   464→			CachedWallDesc.BrickSize
   465→		);
   466→	}
   467→}
   468→
   469→// ---- 충전 시스템 구현 ----
   470→
   471→void UGA_SpawnBrick::ApplyChargeCost()
   472→{
   473→	UAbilitySystemComponent* ASC = GetAbilitySystemComponentFromActorInfo();
   474→	if (!ASC)
   475→	{
   476→		return;
   477→	}
   478→
   479→	const UGameplayEffect* CostGE = UGE_SpawnBrickChargeCost::StaticClass()->GetDefaultObject<UGameplayEffect>();
   480→	if (CostGE)
   481→	{
   482→		FGameplayEffectSpecHandle SpecHandle = MakeOutgoingGameplayEffectSpec(CostGE->GetClass(), GetAbilityLevel());
   483→		if (SpecHandle.IsValid())
   484→		{
   485→			ApplyGameplayEffectSpecToOwner(CurrentSpecHandle, CurrentActorInfo, CurrentActivationInfo, SpecHandle);
   486→		}
   487→	}
   488→}
   489→
   490→void UGA_SpawnBrick::CreateRefillEffect()
   491→{
   492→	if (RefillEffect)
   493→	{
   494→		return;
   495→	}
   496→
   497→	RefillEffect = NewObject<UGameplayEffect>(this, FName(TEXT("GE_SpawnBrickChargeRefill")));
   498→	RefillEffect->DurationPolicy = EGameplayEffectDurationType::Infinite;
   499→	RefillEffect->Period = FScalableFloat(ChargeRefillInterval);
   500→	RefillEffect->bExecutePeriodicEffectOnApplication = false;
   501→
   502→	FGameplayModifierInfo Modifier;
   503→	Modifier.Attribute = UWjWorldCharacterAttributeSet::GetSpawnBrickChargesAttribute();
   504→	Modifier.ModifierOp = EGameplayModOp::Additive;
   505→	Modifier.ModifierMagnitude = FGameplayEffectModifierMagnitude(FScalableFloat(1.f));
   506→	RefillEffect->Modifiers.Add(Modifier);
   507→}
   508→
   509→void UGA_SpawnBrick::StartChargeRefill()
   510→{
   511→	UAbilitySystemComponent* ASC = GetAbilitySystemComponentFromActorInfo();
   512→	if (!ASC || !RefillEffect)
   513→	{
   514→		return;
   515→	}
   516→
   517→	// 이미 리필 중이면 무시
   518→	if (RefillEffectHandle.IsValid() && ASC->GetActiveGameplayEffect(RefillEffectHandle))
   519→	{
   520→		return;
   521→	}
   522→
   523→	FGameplayEffectContextHandle ContextHandle = ASC->MakeEffectContext();
   524→	FGameplayEffectSpec Spec(RefillEffect, ContextHandle, 1.f);
   525→	RefillEffectHandle = ASC->ApplyGameplayEffectSpecToSelf(Spec);
   526→
   527→	// 리필 시작 시각 기록
   528→	if (UWorld* World = GetWorld())
   529→	{
   530→		RefillStartWorldTime = World->GetTimeSeconds();
   531→	}
   532→
   533→	UE_LOG(LogWjWorldAbilities, Log, TEXT("UGA_SpawnBrick: 충전 리필 시작 (%.1f초 간격)"), ChargeRefillInterval);
   534→}
   535→
   536→void UGA_SpawnBrick::StopChargeRefill()
   537→{
   538→	if (!RefillEffectHandle.IsValid())
   539→	{
   540→		return;
   541→	}
   542→
   543→	UAbilitySystemComponent* ASC = GetAbilitySystemComponentFromActorInfo();
   544→	if (ASC)
   545→	{
   546→		ASC->RemoveActiveGameplayEffect(RefillEffectHandle);
   547→	}
   548→
   549→	RefillEffectHandle.Invalidate();
   550→	RefillStartWorldTime = 0.0;
   551→
   552→	UE_LOG(LogWjWorldAbilities, Log, TEXT("UGA_SpawnBrick: 충전 리필 중지 (충전 완료)"));
   553→}
   554→
   555→void UGA_SpawnBrick::OnSpawnBrickChargesChanged(const FOnAttributeChangeData& Data)
   556→{
   557→	UAbilitySystemComponent* ASC = GetAbilitySystemComponentFromActorInfo();
   558→	if (!ASC)
   559→	{
   560→		return;
   561→	}
   562→
   563→	// 리필로 충전이 증가했으면 리필 시작 시각 갱신 (다음 리필까지의 남은 시간 계산용)
   564→	if (Data.NewValue > Data.OldValue && RefillEffectHandle.IsValid())
   565→	{
   566→		if (UWorld* World = GetWorld())
   567→		{
   568→			RefillStartWorldTime = World->GetTimeSeconds();
   569→		}
   570→	}
   571→
   572→	// 서버에서만 리필 관리
   573→	if (!CurrentActorInfo || !CurrentActorInfo->IsNetAuthority())
   574→	{
   575→		return;
   576→	}
   577→
   578→	float MaxChargesValue = ASC->GetNumericAttribute(UWjWorldCharacterAttributeSet::GetMaxSpawnBrickChargesAttribute());
   579→
   580→	// 충전이 최대치에 도달하면 리필 GE 제거
   581→	if (Data.NewValue >= MaxChargesValue && RefillEffectHandle.IsValid())
   582→	{
   583→		StopChargeRefill();
   584→	}
   585→}
   586→
   587→// ---- 충전 조회 메서드 ----
   588→
   589→int32 UGA_SpawnBrick::GetCurrentCharges() const
   590→{
   591→	UAbilitySystemComponent* ASC = GetAbilitySystemComponentFromActorInfo();
   592→	if (!ASC)
   593→	{
   594→		return 0;
   595→	}
   596→	return FMath::TruncToInt32(ASC->GetNumericAttribute(UWjWorldCharacterAttributeSet::GetSpawnBrickChargesAttribute()));
   597→}
   598→
   599→int32 UGA_SpawnBrick::GetMaxCharges() const
   600→{
   601→	return MaxCharges;
   602→}
   603→
   604→float UGA_SpawnBrick::GetChargeRefillTimeRemaining() const
   605→{
   606→	if (!RefillEffectHandle.IsValid() || RefillStartWorldTime <= 0.0)
   607→	{
   608→		return 0.f;
   609→	}
   610→
   611→	const UWorld* World = GetWorld();
   612→	if (!World)
   613→	{
   614→		return 0.f;
   615→	}
   616→
   617→	double Elapsed = World->GetTimeSeconds() - RefillStartWorldTime;
   618→	float Remaining = ChargeRefillInterval - static_cast<float>(Elapsed);
   619→	return FMath::Max(Remaining, 0.f);
   620→}
