   163→bool FWjWorldWallDescription::FindStartingEmptyCell(int32& OutX, int32& OutY)
   164→{
   165→    // 1. 먼저 경계에서 Flood Fill로 외부 영역 마킹
   166→    TSet<FIntPoint> ExteriorCells;
   167→    MarkExteriorCells(ExteriorCells);
   168→
   169→    // 2. 외부 영역이 아닌 내부 빈 셀 찾기
   170→    for (int32 Y = 0; Y < WallLayout.Num(); ++Y)
   171→    {
   172→        for (int32 X = 0; X < WallLayout[Y].Num(); ++X)
   173→        {
   174→            // 빈 셀이면서 외부 영역이 아닌 경우 = 내부 영역
   175→            if (WallLayout[Y][X] == WallCell_Empty && !ExteriorCells.Contains(FIntPoint(X, Y)))
   176→            {
   177→                OutX = X;
   178→                OutY = Y;
   179→                return true;
   180→            }
   181→        }
   182→    }
   183→
   184→    return false;
   185→}
   186→
   187→void FWjWorldWallDescription::MarkExteriorCells(TSet<FIntPoint>& OutExteriorCells)
   188→{
   189→    OutExteriorCells.Empty();
   190→
   191→    const int32 Rows = WallLayout.Num();
   192→    if (Rows == 0) return;
   193→
   194→    const int32 Cols = WallLayout[0].Num();
   195→    if (Cols == 0) return;
   196→
   197→    const TArray<FIntPoint> Directions = {
   198→        { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 }
   199→    };
   200→
   201→    TQueue<FIntPoint> Queue;
   202→
   203→    // 경계(가장자리)에 있는 모든 빈 셀을 시작점으로 추가
   204→    // 상단/하단 행
   205→    for (int32 X = 0; X < Cols; ++X)
   206→    {
   207→        if (WallLayout[0][X] == WallCell_Empty)
   208→        {
   209→            FIntPoint Pt(X, 0);
   210→            if (!OutExteriorCells.Contains(Pt))
   211→            {
   212→                OutExteriorCells.Add(Pt);
   213→                Queue.Enqueue(Pt);
   214→            }
   215→        }
   216→        if (WallLayout[Rows - 1][X] == WallCell_Empty)
   217→        {
   218→            FIntPoint Pt(X, Rows - 1);
   219→            if (!OutExteriorCells.Contains(Pt))
   220→            {
   221→                OutExteriorCells.Add(Pt);
   222→                Queue.Enqueue(Pt);
   223→            }
   224→        }
   225→    }
   226→
   227→    // 좌측/우측 열
   228→    for (int32 Y = 0; Y < Rows; ++Y)
   229→    {
   230→        if (WallLayout[Y][0] == WallCell_Empty)
   231→        {
   232→            FIntPoint Pt(0, Y);
   233→            if (!OutExteriorCells.Contains(Pt))
   234→            {
   235→                OutExteriorCells.Add(Pt);
   236→                Queue.Enqueue(Pt);
   237→            }
   238→        }
   239→        if (WallLayout[Y][Cols - 1] == WallCell_Empty)
   240→        {
   241→            FIntPoint Pt(Cols - 1, Y);
   242→            if (!OutExteriorCells.Contains(Pt))
   243→            {
   244→                OutExteriorCells.Add(Pt);
   245→                Queue.Enqueue(Pt);
   246→            }
   247→        }
   248→    }
   249→
   250→    // Flood Fill: 경계에서 연결된 모든 빈 셀을 외부로 마킹
   251→    while (!Queue.IsEmpty())
   252→    {
   253→        FIntPoint Current;
   254→        Queue.Dequeue(Current);
   255→
   256→        for (const FIntPoint& Dir : Directions)
   257→        {
   258→            const int32 NX = Current.X + Dir.X;
   259→            const int32 NY = Current.Y + Dir.Y;
   260→
   261→            // 범위 체크
   262→            if (NX < 0 || NX >= Cols || NY < 0 || NY >= Rows)
   263→                continue;
   264→
   265→            // 벽이면 통과 불가
   266→            if (WallLayout[NY][NX] >= 1)
   267→                continue;
   268→
   269→            FIntPoint Next(NX, NY);
   270→            if (!OutExteriorCells.Contains(Next))
   271→            {
   272→                OutExteriorCells.Add(Next);
   273→                Queue.Enqueue(Next);
   274→            }
   275→        }
   276→    }
   277→}
   278→
   279→bool FWjWorldWallDescription::IsAreaEnclosedByWalls(int32 StartX, int32 StartY)
   280→{
   281→    const int32 Rows = WallLayout.Num();
   282→    if (Rows == 0) return false;
   283→
   284→    const int32 Cols = WallLayout[0].Num();
   285→
   286→    // 시작 위치 유효성
   287→    if (StartX < 0 || StartX >= Cols || StartY < 0 || StartY >= Rows)
   288→        return false;
   289→
   290→    // 시작 지점이 벽이면 검사 불필요
   291→    if (WallLayout[StartY][StartX] >= 1)
   292→        return true;
   293→
   294→    TQueue<FIntPoint> Queue;
   295→    TSet<FIntPoint> Visited;
   296→
   297→    Queue.Enqueue(FIntPoint(StartX, StartY));
   298→    Visited.Add(FIntPoint(StartX, StartY));
   299→
   300→    const TArray<FIntPoint> Directions = {
   301→        { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 }
   302→    };
   303→
   304→    while (!Queue.IsEmpty())
   305→    {
   306→        FIntPoint Current;
   307→        Queue.Dequeue(Current);
   308→
   309→        for (const FIntPoint& Dir : Directions)
   310→        {
   311→            const int32 NX = Current.X + Dir.X;
   312→            const int32 NY = Current.Y + Dir.Y;
   313→
   314→            if (NX < 0 || NX >= Cols || NY < 0 || NY >= Rows)
   315→            {
   316→                return false;
   317→            }
   318→
   319→            // 벽(1 이상)이면 통과 불가
   320→            if (WallLayout[NY][NX] >= 1)
   321→                continue;
   322→
   323→            FIntPoint Next(NX, NY);
   324→            if (!Visited.Contains(Next))
   325→            {
   326→                Visited.Add(Next);
   327→                Queue.Enqueue(Next);
   328→            }
   329→        }
   330→    }
   331→
   332→    SafeZones.Empty();
   333→    SafeZones.Append(Visited.Array());
   334→
   335→    SafeZonesSet = Visited;
   336→
   337→    // 끝까지 못 나갔으면 완전히 둘러싸임
   338→    return true;
   339→}
   340→
   341→int32 UWjWorldWallDescriptionDataAsset::ScanUserWallLayouts(TArray<FWjWorldWallDescription>& OutUserDescriptions) const
   342→{
   343→    OutUserDescriptions.Empty();
   344→
   345→    FString UserLayoutDir = GetUserWallLayoutDirectory();
   346→
   347→    // 디렉토리 존재 확인
   348→    IFileManager& FileManager = IFileManager::Get();
   349→    if (!FileManager.DirectoryExists(*UserLayoutDir))
   350→    {
   351→        UE_LOG(LogWjWorld, Log, TEXT("ScanUserWallLayouts: User layout directory does not exist: %s"), *UserLayoutDir);
   352→        return 0;
   353→    }
   354→
   355→    // CSV 파일 검색
   356→    TArray<FString> FoundFiles;
   357→    FileManager.FindFiles(FoundFiles, *UserLayoutDir, TEXT("*.csv"));
   358→
   359→    for (const FString& FileName : FoundFiles)
   360→    {
   361→        FString FileNameNoExt = FPaths::GetBaseFilename(FileName);
   362→        FString FullPath = UserLayoutDir / FileName;
   363→
   364→        FWjWorldWallDescription UserDesc;
   365→        UserDesc.WallName = FString::Printf(TEXT("User_%s"), *FileNameNoExt);
   366→        UserDesc.WallLayoutFilePath.FilePath = FullPath;
   367→        UserDesc.BrickSize = FVector(100.0, 100.0, 100.0);  // 기본값
   368→        UserDesc.CenterOffset = FVector::ZeroVector;
   369→
   370→        // ⭐ CSV 파일에서 메타데이터 읽기 (CenterOffset)
   371→        FString FileContent;
   372→        if (FFileHelper::LoadFileToString(FileContent, *FullPath))
   373→        {
   374→            TArray<FString> Lines;
   375→            FileContent.ParseIntoArrayLines(Lines);
   376→
   377→            for (const FString& Line : Lines)
   378→            {
   379→                if (Line.StartsWith(TEXT("#META:CenterOffset:")))
   380→                {
   381→                    FString OffsetStr = Line.RightChop(19); // "#META:CenterOffset:" 제거
   382→                    TArray<FString> Components;
   383→                    OffsetStr.ParseIntoArray(Components, TEXT(","));
   384→
   385→                    if (Components.Num() == 3)
   386→                    {
   387→                        UserDesc.CenterOffset.X = FCString::Atof(*Components[0]);
   388→                        UserDesc.CenterOffset.Y = FCString::Atof(*Components[1]);
   389→                        UserDesc.CenterOffset.Z = FCString::Atof(*Components[2]);
   390→                        UE_LOG(LogWjWorld, Log, TEXT("ScanUserWallLayouts: Parsed CenterOffset (%.1f, %.1f, %.1f) for '%s'"),
   391→                            UserDesc.CenterOffset.X, UserDesc.CenterOffset.Y, UserDesc.CenterOffset.Z, *UserDesc.WallName);
   392→                    }
   393→                    break;
   394→                }
   395→            }
   396→        }
   397→
   398→        OutUserDescriptions.Add(UserDesc);
   399→        UE_LOG(LogWjWorld, Log, TEXT("ScanUserWallLayouts: Found user layout '%s'"), *UserDesc.WallName);
   400→    }
   401→
   402→    return OutUserDescriptions.Num();
   403→}
   404→
   405→TArray<FString> UWjWorldWallDescriptionDataAsset::GetAllWallNames() const
   406→{
   407→    TArray<FString> AllNames;
   408→
   409→    // 내장 레이아웃
   410→    for (const FWjWorldWallDescription& Desc : WallDescriptions)
   411→    {
   412→        AllNames.Add(Desc.WallName);
   413→    }
   414→
   415→    // 유저 레이아웃
   416→    if (!bUserDescriptionsCached)
   417→    {
   418→        ScanUserWallLayouts(CachedUserDescriptions);
   419→        bUserDescriptionsCached = true;
   420→    }
   421→
   422→    for (const FWjWorldWallDescription& UserDesc : CachedUserDescriptions)
   423→    {
   424→        AllNames.Add(UserDesc.WallName);
   425→    }
   426→
   427→    return AllNames;
   428→}
