   430→bool UWjWorldWallDescriptionDataAsset::GetWallDescriptionByNameIncludingUser(const FString& Name, FWjWorldWallDescription& OutDescription) const
   431→{
   432→    // 내장 레이아웃 먼저 검색
   433→    if (GetWallDescriptionByName(Name, OutDescription))
   434→    {
   435→        return true;
   436→    }
   437→
   438→    // 유저 레이아웃 검색
   439→    if (!bUserDescriptionsCached)
   440→    {
   441→        ScanUserWallLayouts(CachedUserDescriptions);
   442→        bUserDescriptionsCached = true;
   443→    }
   444→
   445→    for (const FWjWorldWallDescription& UserDesc : CachedUserDescriptions)
   446→    {
   447→        if (UserDesc.WallName == Name)
   448→        {
   449→            OutDescription = UserDesc;
   450→            return true;
   451→        }
