   460→
   461→    if (AllNames.Num() == 0)
   462→    {
   463→        UE_LOG(LogWjWorld, Error, TEXT("No wall descriptions available (built-in or user)"));
   464→        return FString();
   465→    }
   466→
   467→    int32 RandomIndex = FMath::RandRange(0, AllNames.Num() - 1);
